(globalThis.TURBOPACK||(globalThis.TURBOPACK=[])).push(["object"==typeof document?document.currentScript:void 0,22801,e=>{"use strict";var t=e.i(43476);e.s(["f",0,function({symbols:e}){return(0,t.jsx)("dl",{children:e.map(({element:e,description:a})=>(0,t.jsxs)("div",{children:[(0,t.jsx)("dt",{children:e}),(0,t.jsx)("dd",{children:a})]},e))})}])},1419,64515,e=>{"use strict";var t=e.i(43476),a=e.i(96460),n=e.i(31263),o=e.i(50463);let i="/within";function r(e){return i&&e.startsWith("/")&&!e.startsWith("//")?`${i}${e}`:e}e.s(["f",0,r],64515);var s=e.i(8164),h=e.i(29899);function l({artwork:e}){let{back:n}=a.C[e];return(0,t.jsx)("div",{className:"card-back","data-artwork":e,"data-image-back":!!n,"aria-hidden":"true",children:n?(0,t.jsx)("img",{className:"card-back-image",src:r(n),alt:"",draggable:!1}):(0,t.jsxs)("div",{className:"back-frame",children:[(0,t.jsx)("span",{className:"back-corner corner-one",children:"✧"}),(0,t.jsx)("span",{className:"back-corner corner-two",children:"✧"}),(0,t.jsx)("div",{className:"back-orbit",children:(0,t.jsx)(s.w,{})})]})})}e.s(["I",0,l,"o",0,function({card:e,artwork:i,revealed:s=!0,onReveal:d,revealEnabled:c=!0,className:u="",label:m,thumbnail:g=!1}){let{locale:p,text:f}=(0,h.useLanguage)(),w=(0,o.U)(e,p),y={"--card-height-ratio":a.C[i].ratio},b=(0,t.jsxs)("div",{className:`card-flipper ${s?"is-revealed":""}`,children:[(0,t.jsx)("div",{className:"card-face card-reverse",children:!s||d?(0,t.jsx)(l,{artwork:i}):null}),(0,t.jsxs)("div",{className:"card-face card-front","aria-hidden":!s,children:[s&&(0,t.jsx)("img",{src:r((0,n.i)(e,i,g?"thumbnail":"detail")),alt:e.numeral?f.artwork(w,e.numeral):w,loading:g?"lazy":void 0,draggable:"false"}),s&&"van-gogh"===i&&(0,t.jsxs)("div",{className:"painted-card-caption","aria-hidden":"true",children:[(0,t.jsx)("span",{className:"painted-card-number",children:e.numeral}),(0,t.jsx)("span",{className:"painted-card-name",children:w})]})]})]});return d?(0,t.jsx)("button",{className:`tarot-card ${u}`,"data-artwork":i,style:y,onClick:d,disabled:s||!c,"aria-label":s?w:m||f.reveal,children:b}):(0,t.jsx)("div",{className:`tarot-card ${u}`,"data-artwork":i,style:y,children:b})}],1419)},31263,7364,50463,e=>{"use strict";var t=e.i(96460),a=e.i(5511);function n(e,t){return{uprightMeaning:e.upright[t],traditionalInterpretation:e.traditional[t],symbolism:e.symbols.map(({name:e,meaning:a})=>({element:e[t],description:a[t]})),reflectionPrompts:e.prompts.map(e=>e[t])}}function o(e,t){return{...e,imagePath:`/cards/${e.id}.svg`,...n(t,0),zh:n(t,1),reference:`https://en.wikisource.org/wiki/Page:The_Pictorial_Key_to_the_Tarot.pdf/${t.sourcePage}`}}let i={"cups-ace":{sourcePage:238,upright:["Something small may have reached you before you found words for it. The Ace of Cups makes room for a feeling, an invitation, or a kindness you might usually hurry past. Give it a little time. You can receive it without deciding yet what it means or what you owe in return.","有些感受先抵达，语言才慢慢跟上。圣杯王牌给一份情绪、一个邀请，或一点平时会匆匆略过的善意留出空间。让它多待一会儿。你可以先收下，等一等再想它意味着什么。"],traditional:["Waite places joy, nourishment, and abundance around an overflowing cup. The water and dove make receiving and renewal visible. Within reads that image as an opening in everyday life.","韦特把喜悦、滋养与丰盛联系到这只满溢的杯子。水流和鸽子让接纳与新生有了形状。Within 借这个画面来想象日常里刚打开的一点空间。"],symbols:[{name:["The overflowing cup","满溢的杯子"],meaning:["A feeling or kindness with room to spill beyond itself.","一份感受或善意有了向外流动的余地。"]},{name:["The descending bird","落下的鸟"],meaning:["Something arrives before you have to reach for it.","有些东西会在你主动伸手前先抵达。"]},{name:["The ripples","水纹"],meaning:["A small change can travel quietly through ordinary life.","小变化也会悄悄传进平常的生活。"]}],prompts:[["What kindness could you accept today without explaining it away?","今天，有哪份善意可以让你安静地收下？"],["Which new feeling deserves a little more room?","哪个刚出现的感受，值得你多留一点空间？"]]},"cups-two":{sourcePage:236,upright:["Pay attention to where an exchange feels mutual. The Two of Cups invites one small act of meeting halfway, such as saying what you need or letting someone tell you what they need. Agreement can be modest and still matter. Give each person enough space to answer honestly.","留意哪些交流里，双方都能自在地给出和接受。圣杯二邀请你做一件向对方靠近的小事，比如说出自己的需要，或给对方时间表达他们的需要。哪怕只是达成一点共识，也值得珍惜。"],traditional:["Waite associates this exchange of cups with affinity, friendship, and accord. The pair and the emblem above them make the relationship itself the focus of the scene.","韦特把交换杯子的画面与亲近、友谊和和谐联系起来。两个人与上方的徽记，把注意力引向他们之间的关系。"],symbols:[{name:["The matching cups","成对的杯子"],meaning:["Each person has something to offer and something to receive.","两个人都可以给出，也都可以接受。"]},{name:["The space between","两人之间的距离"],meaning:["Closeness makes space for two independent voices.","亲近也能给各自的声音留下位置。"]},{name:["The winged emblem","带翼的徽记"],meaning:["The connection takes shape through both people’s choices.","这段连接由两个人的选择共同形成。"]}],prompts:[["Where would a small, honest exchange make a relationship more mutual?","在哪段关系里，一次坦诚的小交流会让双方更有来有往？"],["What would you like to give, and what could you ask for?","你愿意给出什么？又想开口请求什么？"]]},"cups-three":{sourcePage:234,upright:["Some good things become more real when someone shares them with you. The Three of Cups invites you to notice a contribution worth thanking, a friend worth calling, or an ordinary milestone worth marking. Let the gathering fit the people in it. A short conversation can be enough.","有些好事在与人分享时才真正有了分量。圣杯三邀请你留意，哪份付出值得道谢，哪位朋友值得联系，或哪个寻常的小进展值得庆祝。让相聚的方式适合在场的人，一次短短的交谈也可以。"],traditional:["Waite describes cups raised together and associates the scene with a happy conclusion, comfort, and recovery. The people make the moment something they can share.","韦特描写了一起举杯的场景，并将它与圆满、安慰和恢复联系起来。在场的人让这个时刻变成一件能够共同感受的事。"],symbols:[{name:["Raised cups","举起的杯子"],meaning:["Acknowledging a moment together gives it weight.","共同承认一个时刻，会让它更有分量。"]},{name:["Three figures","三个人"],meaning:["Each person brings something different to the gathering.","每个人给这次相聚带来不同的东西。"]},{name:["Leaves below","脚下的叶子"],meaning:["Ordinary growth is worth noticing.","平常的生长也值得被看见。"]}],prompts:[["Who helped make a recent good moment possible, and how could you thank them?","最近的一件好事里，谁出了一份力？你可以怎样谢谢对方？"],["What small occasion would you enjoy sharing?","你想和谁分享哪一个小小的时刻？"]]},"cups-four":{sourcePage:232,upright:["When everything feels a little flat, you can pause before answering another invitation. The Four of Cups asks you to notice whether you need rest, room to feel disappointed, or a change in what you are paying attention to. Give the feeling time to become specific. Then decide what to do with the offer in front of you.","当什么都提不起劲时，可以晚一点再回应新的邀请。圣杯四请你看看，自己需要休息、需要一点时间感受失望，还是想换个地方投注注意力。等感受变得具体一些，再决定怎样面对眼前的提议。"],traditional:["In Waite’s account a seated figure notices little comfort in a cup being offered. Weariness and mixed pleasure sit alongside the three cups already present.","韦特笔下，坐着的人很难从递来的杯子里感到安慰。已经摆在面前的三只杯子，和疲倦、复杂的满足感一起留在画面中。"],symbols:[{name:["The seated figure","坐着的人"],meaning:["A pause in which your own reaction can become clearer.","停一停，让自己的反应变得更清楚。"]},{name:["Three cups on the ground","地上的三只杯子"],meaning:["Familiar choices can start to feel alike.","熟悉的选项有时会慢慢失去区别。"]},{name:["The offered cup","递来的杯子"],meaning:["An invitation you can consider in your own time.","一个可以按自己的节奏考虑的邀请。"]}],prompts:[["What would help you tell the difference between needing rest and wanting a change?","什么能帮你分清，自己是需要休息，还是想改变一点什么？"],["Which invitation could you reconsider when you have more energy?","等精力回来一些，哪个邀请可以重新考虑？"]]},"cups-five":{sourcePage:230,upright:["Disappointment deserves some time before you try to make a lesson out of it. The Five of Cups lets you name what was lost and, when you are ready, notice what can still support you. Give both realities their own place. A small act of care can help you take the next step at your own pace.","先给失望一点时间，再慢慢想能从中学到什么。圣杯五邀请你说清失去了什么，等准备好了，再看看还有什么能支持你。两件事都可以被承认。照顾自己的一个小动作，也能帮你按自己的节奏走下一步。"],traditional:["Waite describes loss alongside what remains. Three cups have fallen and two are still standing. The bridge in the scene gives that contrast a direction to look toward.","韦特同时写到损失与留下的东西。三只杯子已经倒下，两只仍然立着。画面里的桥让目光还能往前看一点。"],symbols:[{name:["Three fallen cups","三只倒下的杯子"],meaning:["A loss can be named in its own terms.","可以直接说出这次失去带来的感受。"]},{name:["Two standing cups","两只立着的杯子"],meaning:["Some sources of support may still be available.","有些支持仍然在你身边。"]},{name:["The bridge","桥"],meaning:["A way forward can exist before you feel ready to take it.","还没准备好往前走时，路也可以先在那里。"]}],prompts:[["What do you need to acknowledge about this loss, and what is still available to you?","这次失去有什么需要承认？此刻还有什么能帮到你？"],["What would make the next hour a little kinder?","做什么能让接下来的一个小时好过一点？"]]},"cups-six":{sourcePage:228,upright:["A memory can offer a clue about something you still need. The Six of Cups invites you to revisit a familiar place, a way of playing, or a small kindness that stayed with you. Choose one part worth bringing into the present. Let it take a shape that fits who you are now.","一段回忆有时会提醒你，现在仍然需要什么。圣杯六邀请你重想一个熟悉的地方、一种玩耍的方式，或一份留在记忆里的善意。挑一样值得带回当下的东西，让它以适合今天的方式重新出现。"],traditional:["Waite links this card with childhood and pleasures recalled from the past, while also recording a reading about unfamiliar surroundings. Flowers offered between the figures connect memory with a gesture in the present.","韦特把这张牌与童年和往日的快乐联系起来，也记下了关于陌生环境的另一种读法。两个人之间递出的花，把回忆和眼前的动作连在一起。"],symbols:[{name:["The courtyard","庭院"],meaning:["A place remembered through the feeling it held.","一个因为曾有的感受而被记住的地方。"]},{name:["The flower in a cup","杯中的花"],meaning:["A small gesture can carry something from the past.","小小的举动也能把往日的一点东西带回来。"]},{name:["The cups in front","前排的杯子"],meaning:["The past holds more than the memory that first comes to mind.","回忆里还有许多东西，会在第一段记忆之后慢慢浮现。"]}],prompts:[["What did you enjoy when you were younger that could fit your life now?","小时候喜欢的哪件事，今天仍可以给它留一点位置？"],["Which remembered kindness would you like to pass on?","你想把记忆里的哪份善意传给别人？"]]},"cups-seven":{sourcePage:226,upright:["Several possibilities can feel equally convincing while they are still in your head. The Seven of Cups invites you to put one of them into words, then ask what you can actually observe or try. Imagination can widen the field. A small test can show which possibility is ready for your attention.","几种可能还只停留在想象里时，往往都让人心动。圣杯七邀请你先把其中一种说具体，再问自己，眼下能观察到什么、能试做什么。想象帮你打开选项，一个小试验能让你看清哪种值得继续。"],traditional:["Waite associates the cups in clouds with imagination and images of contemplation. Their contents have different attractions, and their place above the ground keeps the scene suspended between imagining and acting.","韦特把云中的杯子与想象和沉思时出现的图景联系起来。杯里各有不同的吸引力，悬浮的位置让画面停在想象与行动之间。"],symbols:[{name:["Seven vessels","七只杯子"],meaning:["Different possibilities can call for attention at once.","许多不同的可能会同时吸引你的注意。"]},{name:["The floating shapes","悬浮的图形"],meaning:["An imagined choice still has details to discover.","想象中的选择还有待了解的细节。"]},{name:["The observer","观察者"],meaning:["Take enough distance to decide what to examine first.","退开一点，看看自己想先了解哪一种可能。"]}],prompts:[["Which possibility could you test without committing to it yet?","你可以先试试哪一种可能，同时给自己留着回头的余地？"],["What information would help you tell two appealing options apart?","什么信息能帮你分辨两个都很吸引你的选项？"]]},"cups-eight":{sourcePage:224,upright:["A situation can have given you something and still feel complete. The Eight of Cups invites you to consider where your energy is needed now. Try naming what you would carry with you and what you could put down. You can mark the change with one deliberate step, even if the rest of the route is still uncertain.","一件事曾经给过你很多，如今也可以走到结束。圣杯八邀请你看看，接下来哪里更需要你的精力。试着说出你想带走什么、可以放下什么。哪怕后面的路还不清楚，也可以先踏出一步，承认变化已经开始。"],traditional:["Waite describes a figure leaving arranged cups and discusses a waning concern or a change in what seems important. He also records contrasting readings. The night landscape gives Within’s scene room for uncertainty.","韦特描写了离开一排杯子的人，也谈到一件事逐渐衰退、重要性改变的读法，并记录了相反的解释。Within 画里的夜色给这种不确定留出空间。"],symbols:[{name:["Cups left behind","留下的杯子"],meaning:["What you built can matter after your priorities change.","即使重点变了，曾经做过的事仍然有价值。"]},{name:["A path uphill","上坡的小路"],meaning:["A direction you can begin to follow before you see its end.","还没看见终点，也可以沿着一个方向走一小段。"]},{name:["The moon","月亮"],meaning:["Enough light to see the next step.","光线只够看清下一步，也已经有用。"]}],prompts:[["What can you put down while still valuing what it gave you?","哪件事可以放下，同时珍重它曾经带给你的东西？"],["What is one step toward what matters now?","朝着现在在乎的事，你能先迈出哪一步？"]]},"cups-nine":{sourcePage:222,upright:["There is value in recognizing a moment of enough. The Nine of Cups invites you to notice what you can actually enjoy, whether it came from effort, luck, or someone else’s care. Let yourself appreciate it before you begin measuring the distance to the next thing.","认出一个「已经足够」的时刻，本身就有价值。圣杯九邀请你留意，眼下真正能享受的是什么，无论它来自努力、运气，还是别人的照料。开始计算离下一件事还有多远之前，先感受一下已经拥有的东西。"],traditional:["Waite connects this seated figure and the arranged cups with contentment, well-being, and satisfaction. The display makes visible what has already been gathered.","韦特把坐着的人和摆好的杯子与满足、安适联系起来。排列整齐的杯子让已经积累的东西变得可见。"],symbols:[{name:["Nine cups on display","陈列的九只杯子"],meaning:["A chance to see what has already come together.","看见已经汇集到手中的东西。"]},{name:["The seat","座椅"],meaning:["Satisfaction can be a pause you choose to take.","满足可以从允许自己停一会儿开始。"]},{name:["The open floor","空着的地面"],meaning:["An ordinary moment can have space of its own.","寻常的一刻也值得拥有自己的空间。"]}],prompts:[["What is enough for you today, even if it is smaller than you expected?","即使比预想的要小，今天有哪些东西已经足够？"],["What pleasure could you let yourself notice before moving on?","继续向前之前，你愿意先感受哪份愉快？"]]},"cups-ten":{sourcePage:220,upright:["Belonging is often made out of repeated, ordinary acts. The Ten of Cups asks you to notice the people and places around whom you can breathe more easily. You might take care of one small ritual, offer a welcome, or make a little time for someone who makes life feel more inhabitable.","归属感往往来自一再发生的寻常小事。圣杯十邀请你留意，哪些人和地方让你呼吸更轻松。你可以照顾一个小习惯，向谁说声欢迎，或给让生活更安稳的人留一点时间。"],traditional:["Waite associates the arch of cups with contentment, love, and friendship, and allows for a reading connected with one’s home or community. Within places an open doorway under the arch.","韦特把杯子组成的弧形与满足、爱和友谊联系起来，也提到家园与共同体的读法。Within 在弧形下方画了一扇敞开的门。"],symbols:[{name:["The arc of cups","杯子组成的弧形"],meaning:["Many small moments can form a shared sense of safety.","许多小小的时刻能够积成共同的安心感。"]},{name:["The open doorway","敞开的门"],meaning:["Belonging can begin with a gesture of welcome.","归属感可以从一个欢迎的动作开始。"]},{name:["The two figures","两个人"],meaning:["A shared place can hold more than one way of being there.","同一个地方，可以容纳彼此不同的相处方式。"]}],prompts:[["What small ritual helps a place or relationship feel like somewhere you belong?","哪个小习惯会让一个地方或一段关系更有归属感？"],["What could you do to make someone feel welcome this week?","这周你能做什么，让某个人感到被欢迎？"]]},"cups-page":{sourcePage:218,upright:["A surprising reaction can be a useful beginning. The Page of Cups invites you to stay curious about a feeling, image, or idea that seems a little odd. Try writing it down, sketching it, or asking what made you notice it. Let the first experiment stay small and playful.","出乎意料的反应，有时是个好开头。圣杯侍从邀请你对一份古怪的感受、画面或想法多留一点好奇。试着记下来、画出来，或问问它为何吸引你。让第一次尝试轻松一点，小一点。"],traditional:["In Waite’s description a fish appears from the cup. The court card is associated with a message, study, and reflection. The surprising image makes curiosity part of the encounter.","韦特描写了一条从杯中出现的鱼。这张宫廷牌与消息、学习和反思有关。出乎意料的画面，也给相遇带来了一点好奇。"],symbols:[{name:["The fish","鱼"],meaning:["An unexpected detail worth being curious about.","一个值得多留意一下的意外细节。"]},{name:["The held cup","手中的杯子"],meaning:["A feeling you can examine gently and at close range.","可以轻轻捧着、靠近一点看清的感受。"]},{name:["The shore","岸边"],meaning:["A place where an inner impression can meet an ordinary action.","让内心的印象与寻常行动相遇的地方。"]}],prompts:[["Which small surprise would be fun to follow for ten minutes?","哪个小小的意外，值得你花十分钟追下去看看？"],["How could you make a feeling visible without needing to explain it?","你能怎样让一种感受变得可见，同时不急着解释它？"]]},"cups-knight":{sourcePage:216,upright:["A sincere offer becomes clearer when it has a concrete form. The Knight of Cups invites you to move toward what matters with a pace the other person can respond to. Draft the invitation, make the gesture, or take a first step. Leave room for the answer to surprise you.","真诚的提议有了具体形状，别人也更容易明白。圣杯骑士邀请你朝在乎的事迈一步，同时给对方留出回应的时间。可以写一条邀请，做一个小动作，或者先问一句。让接下来的回答有它自己的可能。"],traditional:["Waite links the approaching rider to invitations, proposals, and messages. The cup is carried openly, making the offer visible before it arrives.","韦特把渐渐走近的骑士与邀请、提议和消息相连。杯子被举在身前，让人还没走到眼前就能看见他的来意。"],symbols:[{name:["The moving horse","前行的马"],meaning:["A feeling starts to take shape through movement.","一个感受在行动中慢慢有了形状。"]},{name:["The open cup","敞开的杯子"],meaning:["A gesture someone else can freely respond to.","一份别人可以自由回应的善意。"]},{name:["The water at the edge","边缘的水面"],meaning:["The pace of the encounter matters as much as its intention.","相遇的节奏和初衷一样值得留意。"]}],prompts:[["What invitation could you make clearly, with room for a real answer?","你可以发出怎样的邀请，说清来意，也给对方留出回答的空间？"],["What small action would make a good intention easier to understand?","什么小动作能让别人更容易理解你的好意？"]]},"cups-queen":{sourcePage:214,upright:["Listening closely can be a form of care. The Queen of Cups invites you to notice what someone is feeling, including yourself, and decide what needs an answer now. Give the parts that are still tender some privacy. Your attention can be generous while your boundaries stay clear.","认真听一听，本身就是一种照料。圣杯王后邀请你留意别人和自己的感受，再决定眼下什么需要回应。还很脆弱的部分，可以先留一点私密空间。你可以大方地给出关注，同时清楚自己的边界。"],traditional:["Waite associates the Queen with perceptive care and a richly formed cup. The seated figure studies the vessel at the water’s edge. Within reads that attention as something available to anyone.","韦特把王后与敏锐的关怀和一只精巧的杯子联系起来。坐在水边的人专注地看着手中的杯。Within 把这种细心看作人人都可以练习的事。"],symbols:[{name:["The lidded cup","带盖的杯子"],meaning:["A feeling can be held carefully before it is shared.","有些感受可以先好好放在心里，等准备好了再分享。"]},{name:["The arched seat","拱形座椅"],meaning:["A boundary that gives quiet attention somewhere to rest.","有了边界，安静的注意力也有地方落下。"]},{name:["Water at the feet","脚下的水"],meaning:["You can stay close to a feeling without being carried away by it.","可以靠近一种感受，同时保有自己的立足点。"]}],prompts:[["Which feeling needs a patient listener, and what boundary would make that listening possible?","哪种感受需要被耐心听见？怎样的边界能让这次倾听成为可能？"],["What would it mean to give yourself the attention you give someone you care about?","把给在乎的人的那份关注也给自己，你会怎么做？"]]},"cups-king":{sourcePage:212,upright:["Steadiness can give everyone a little more room to think. The King of Cups asks you to name what you feel before deciding how to respond, especially when your choices affect other people. Try making one response clear and kind. You can return to the harder parts when you have more time.","稳一点，能让在场的人都多一点思考的空间。圣杯国王邀请你先辨认自己的感受，再决定怎么回应，尤其是选择会影响别人时。试着给出一个清楚又温和的回应，更难的部分可以等有了时间再处理。"],traditional:["Waite links this court card with responsibility, fair dealing, and creative intelligence. The seat above moving water gives a concrete image of staying present in changing conditions.","韦特把这张宫廷牌与责任、公允和创造性的判断联系起来。流动水面上的座椅，让人在变化中保持在场有了一个具体形象。"],symbols:[{name:["The raised seat","高起的座椅"],meaning:["A steady vantage point from which to decide how to act.","有一个稳当的位置，可以慢慢决定如何行动。"]},{name:["The cup and scepter","杯子与权杖"],meaning:["Care and responsibility can guide the same response.","关怀和责任可以一起指引一次回应。"]},{name:["The small boat","小船"],meaning:["Other lives keep moving around the choices you make.","作出选择时，周围的人也有各自正在继续的生活。"]}],prompts:[["What would a steady, kind response to this situation sound like?","面对这件事，一个稳当又温和的回应会是什么样？"],["How could you make room for a feeling before acting on it?","行动之前，你可以怎样先给自己的感受留一点空间？"]]}},r=a.Y.cups.map(e=>o(e,i[e.id])),s={"wands-ace":{sourcePage:210,upright:["There may be an idea you keep returning to even when nobody asks you to. The Ace of Wands invites you to give it a small beginning. Sketch a version, set out the tools, or spend ten minutes trying it. The first step can help you learn what kind of interest this is.","也许有个想法，即使没人催促，你也会一再想起。权杖王牌邀请你给它一个小小的开头。画个草图、摆出工具，或者先试十分钟。走出第一步，你就能更清楚自己究竟对哪里感兴趣。"],traditional:["Waite places creation, enterprise, and beginnings around a wand offered from a cloud. In Within’s drawing, the leaves are the first signs that the idea has somewhere to grow.","韦特笔下，一根权杖从云中伸出，关联创造、尝试与开端。Within 用权杖上新长出的叶子，表现想法刚有了生长的地方。"],symbols:[{name:["The budding wand","发芽的权杖"],meaning:["An idea can be alive before it has a finished form.","想法还没有成形，就已经有了生机。"]},{name:["The cloud","云"],meaning:["An impulse appearing while the larger picture is still unclear.","全貌还不清楚时，先出现的一点冲动。"]},{name:["The distant ridge","远处的山脊"],meaning:["A horizon you can approach one experiment at a time.","远处的方向，可以用一次次小尝试来靠近。"]}],prompts:[["What could you begin in ten minutes with what you already have?","用手头已有的东西，你能在十分钟内开始什么？"],["What part of the idea still interests you when nobody is watching?","没人看着时，这个想法的哪个部分仍然吸引你？"]]},"wands-two":{sourcePage:208,upright:["Stand still long enough to notice what your current position makes possible. The Two of Wands invites you to compare the place you know with one direction you could explore. Give that direction a concrete detail, such as a conversation to have or a place to visit. You can gather information before committing.","先站稳，看看你现在的位置给了你哪些可能。权杖二邀请你把熟悉的处境和一个想探索的方向放在一起看。给那个方向添上一点具体内容，比如想聊的一场谈话，或想去看看的地方。决定之前，可以先了解它。"],traditional:["Waite describes a figure holding a globe on a high terrace and records sharply different readings of the card. The scene gives Within a way to ask how having a wide view affects what you want to do next.","韦特描写了在高处手持地球仪的人，也记下了彼此差异很大的牌义。Within 借这个场景来问，当视野变宽，你想做的下一件事会怎样改变？"],symbols:[{name:["The terrace","高处的平台"],meaning:["The position you already have can help you see farther.","你已经拥有的位置，能帮你看得更远。"]},{name:["The globe","地球仪"],meaning:["An imagined direction can become specific enough to explore.","想象中的方向可以变得具体，足以去看一看。"]},{name:["Two upright wands","两根立着的权杖"],meaning:["A familiar foothold and a possible departure can be considered together.","熟悉的立足点和可能的出发，可以同时考虑。"]}],prompts:[["What could you learn about a possible direction before deciding on it?","决定一个方向之前，你还可以先了解什么？"],["Which part of your current position would you want to carry with you?","现在的位置给了你什么，是你想带去下一段路的？"]]},"wands-three":{sourcePage:206,upright:["An effort can change once it starts reaching other people. The Three of Wands invites you to look for signs of what has left your hands and what still needs your attention. A useful next step may be to ask for feedback, make a connection, or give work already in motion time to travel.","一件事开始接触到别人后，往往会有新的变化。权杖三邀请你看看，什么已经从你手中出发，什么还需要你照看。你可以问问反馈、联系一个人，或者给已经启程的事情多一点时间。"],traditional:["In Waite’s account a figure watches ships from a height. The card is associated with enterprise, discovery, and cooperation. The ships carry the work beyond the place where it began.","韦特描写了从高处望着船只的人，这张牌与拓展、探索和协作有关。船把已经开始的工作带到了更远的地方。"],symbols:[{name:["The three posts","三根立柱"],meaning:["Work already done can support a wider view.","已经做过的事，可以支撑你看得更远。"]},{name:["The ships","船只"],meaning:["A project begins to meet conditions outside your control.","一件事出发后，会遇到你掌控之外的条件。"]},{name:["The overlook","眺望处"],meaning:["Take stock before adding another effort.","再加一份力之前，先看看已经走到了哪里。"]}],prompts:[["Who could help you see how your work is landing beyond your own view?","谁能帮你看见，这份努力在你看不到的地方产生了什么影响？"],["What is already moving that could use more time?","哪件已经在推进的事，可以先给它一点时间？"]]},"wands-four":{sourcePage:204,upright:["A pause to mark progress can make the work feel more real. The Four of Wands invites you to notice the people or routines that gave this effort a place to land. Make a small occasion of it. A meal, a message, or a few quiet minutes can give a milestone its own place.","停下来记下一个进展，能让努力变得更真实。权杖四邀请你留意，是哪些人或习惯让这件事有了落脚的地方。用一顿饭、一条消息，或几分钟的安静，把这个节点单独留出来。"],traditional:["Waite describes four wands bearing a garland and associates the scene with refuge, concord, and work brought to completion. The opening beneath the garland reads as a place to gather.","韦特描写了四根权杖托起的花环，并将画面与安歇、和谐和一段工作的完成联系起来。花环下方的开口，像一个可以相聚的地方。"],symbols:[{name:["Four supports","四根支柱"],meaning:["Several ordinary supports can make a place feel dependable.","几件平常的支撑，可以让一个地方变得可靠。"]},{name:["The garland","花环"],meaning:["A deliberate gesture that marks an occasion.","用一个有意的动作记住这个时刻。"]},{name:["The open threshold","敞开的门槛"],meaning:["A place where someone else can join the moment.","一个可以邀请别人共同感受的地方。"]}],prompts:[["What small milestone deserves to be marked, and who helped you reach it?","哪个小小的节点值得庆祝？谁帮你走到了这里？"],["What would make a pause feel restorative for you?","怎样停一下，才会让你真正恢复一点力气？"]]},"wands-five":{sourcePage:202,upright:["Several people can care about the same thing and still pull it in different directions. The Five of Wands invites you to ask what everyone is trying to protect or prove. Try naming one rule that would make the disagreement more useful, or one part of it you can turn into a small test.","几个人可以同样在乎一件事，却把它拉向不同方向。权杖五邀请你问问，大家分别想保护什么、证明什么。可以先说出一条让争论更有收获的规则，或者把其中一个分歧变成能试做的小实验。"],traditional:["Waite describes a mock fight and also connects the card with strenuous competition. The crossed wands leave space to ask whether the struggle is practice, friction, or both.","韦特描述了一场模拟的打斗，也把这张牌和激烈竞争联系起来。交错的权杖让人可以问，这场较量里，哪些是练习，哪些是摩擦？"],symbols:[{name:["Five crossed wands","五根交错的权杖"],meaning:["Different aims can meet without immediately fitting together.","不同的目标相遇时，一开始可能并不合拍。"]},{name:["The circle below","下方的圆环"],meaning:["Shared limits can turn friction into practice.","共同的边界能让摩擦变成练习。"]},{name:["The gaps between strokes","线条之间的空隙"],meaning:["Even in conflict there may be room to change your approach.","即使在冲突里，也可能有调整做法的空间。"]}],prompts:[["What rule or small test could make this disagreement more useful?","哪一条规则或哪个小尝试，能让这次分歧更有收获？"],["What is each person trying to protect?","在这次分歧里，各自想保护的是什么？"]]},"wands-six":{sourcePage:200,upright:["Recognition can be a moment to see what really went well. The Six of Wands invites you to accept an acknowledgment, notice the people who helped, and name what you would repeat. Let this one result have a place without asking it to predict the next one.","被看见时，可以顺便看清究竟哪里做得好。权杖六邀请你收下一份肯定，想想谁帮过你，以及哪种做法值得再用一次。给这次结果留一个位置，下一次会怎样，可以留给下一次。"],traditional:["Waite reads the laurel-bearing rider as a figure of victory and also as a bearer of significant news. Within brings the raised wreath and the other wands into the same procession.","韦特把带着桂冠的骑者与胜利和重要的消息联系起来。Within 让高举的桂冠和其他权杖出现在同一支行列里。"],symbols:[{name:["The wreath","桂冠"],meaning:["A sign that a particular effort has been seen.","某一份具体的努力得到了看见。"]},{name:["The rider","骑者"],meaning:["Receiving credit is a moment you can pause to inhabit.","接受肯定时，可以停一停，感受这个时刻。"]},{name:["The accompanying wands","同行的权杖"],meaning:["The work often had support beyond the most visible person.","成果背后，往往还有最显眼的人之外的支持。"]}],prompts:[["What went well that you would like to repeat, and whose help made it possible?","哪一点做得好，值得你再做一次？谁的帮助让它成为可能？"],["How could you accept a compliment without immediately changing the subject?","收到一句肯定时，你能怎样先收下它？"]]},"wands-seven":{sourcePage:198,upright:["You can choose which challenges deserve a response. The Seven of Wands invites you to name the position you want to hold and the amount of energy it deserves. A clear boundary, a short explanation, or a deliberate pause may serve you better than answering every pressure at once.","你可以选择哪些挑战值得回应。权杖七邀请你说清想守住的是什么，以及它值得多少精力。一个明确的界限、一句简短的说明，或有意识地停一下，都能给你留下选择的余地。"],traditional:["Waite describes one figure meeting six raised wands from higher ground. He connects the scene with courage, debate, and negotiation. The vantage point matters as much as the pressure below it.","韦特描写了一个站在高处、面对六根举起的权杖的人，并将画面与勇气、争论和协商联系起来。立足的位置和下方的压力同样值得留意。"],symbols:[{name:["The raised ground","高处的立足点"],meaning:["Recognize the position and support you already have.","看见你已经拥有的位置与支持。"]},{name:["The diagonal wand","斜举的权杖"],meaning:["A boundary can be held with a deliberate gesture.","一个清楚的动作，也能守住边界。"]},{name:["Six approaching wands","靠近的六根权杖"],meaning:["Several demands can arrive without all requiring an answer.","许多要求可以同时到来，你可以挑需要回应的。"]}],prompts:[["Which boundary is worth holding, and which challenge can you let pass?","哪条边界值得守住？哪一个挑战可以先让它过去？"],["What short sentence would make your position clear?","哪一句简短的话，可以让别人明白你的立场？"]]},"wands-eight":{sourcePage:196,upright:["Momentum can make the next step easier to see. The Eight of Wands invites you to sort what needs a prompt response from what can wait. Pick one action that carries the work forward and give the rest a place to land. Moving quickly can still leave time to check your direction.","事情一旦有了势头，下一步可能更容易看清。权杖八邀请你分出哪些事需要及时回应，哪些可以等等。先做一件能让工作向前的事，再给其他事项安排落脚点。走得快时，也可以看看方向。"],traditional:["Waite describes eight wands in flight and associates them with swiftness and activity already under way. Within places open country beneath their shared direction.","韦特描写了飞行中的八根权杖，将它们与速度和已经开始的行动联系起来。Within 在它们共同的方向下方，留出一片开阔的土地。"],symbols:[{name:["The flying wands","飞行的权杖"],meaning:["Several events can move at once.","几件事可以同时向前推进。"]},{name:["The shared angle","一致的倾斜方向"],meaning:["Momentum is easier to use when the direction is clear.","方向清楚时，势头更容易用起来。"]},{name:["The open ground","开阔的地面"],meaning:["Something in motion still needs a place to land.","正在前进的事，也需要一个落脚点。"]}],prompts:[["Which timely action would move things forward without scattering your attention?","哪件及时的小行动能推进事情，又不分散你的注意力？"],["What could you put aside until this burst of activity settles?","这阵忙碌过去之前，哪件事可以先放一放？"]]},"wands-nine":{sourcePage:194,upright:["Experience may have taught you to stay alert. The Nine of Wands invites you to notice which precautions still help and where you can let the strain ease. Decide what support, rest, or clearer limit would make the next stretch sustainable.","经历可能让你习惯保持警惕。权杖九邀请你分清，哪些防备现在仍有帮助，哪些地方可以松一点。看看什么支持、休息或更清楚的界限，能让下一段路走得更久。"],traditional:["Waite’s figure holds a staff before eight others and appears ready for opposition. His account also allows for delays and pauses. The scene holds both preparedness and the wear of staying ready.","韦特画面里的人握着一根杖，背后还有八根，像是在准备应对阻力。他也写到延迟和暂停。这幅画同时留住了准备与长期警觉带来的疲惫。"],symbols:[{name:["The held staff","手中的杖"],meaning:["Use the support you already know works.","用上那些你已经知道可靠的支撑。"]},{name:["The line behind","身后的一排权杖"],meaning:["Past effort has built some protection around you.","以前的努力已经在身边建起一些保护。"]},{name:["The head wrap","额上的布带"],meaning:["What you have carried can affect what you need next.","你已经承受的东西，会影响下一步需要什么。"]}],prompts:[["What would let you stay prepared without staying tense all day?","怎样既能有所准备，又不必整天绷着？"],["Which support would make the next stretch easier to sustain?","哪一种支持能让你更稳地走完下一段？"]]},"wands-ten":{sourcePage:192,upright:["Work you care about can still become heavy. The Ten of Wands invites you to look at the load as separate commitments. Which one needs you, which can be shared, and which could wait? Choose one adjustment before the whole bundle decides how you spend your day.","在乎的事也可能变得很重。权杖十邀请你把重担拆成一项项承诺来看。哪一项需要你亲自做，哪一项可以分担，哪一项能晚一点？先选一个能调整的地方，让你还能安排自己的时间。"],traditional:["Waite shows a person bent under ten staffs and includes the burden that can come with success among the readings. The destination is visible while the load takes up most of the view.","韦特描写了被十根权杖压弯的人，也提到成果可能带来的负担。目的地仍然可见，但眼前的大部分视野已经被重担占住。"],symbols:[{name:["Ten staffs in a bundle","捆在一起的十根权杖"],meaning:["A load may be easier to change when you can name its parts.","看清重担由哪些事情组成，才容易调整。"]},{name:["The bent figure","弯着身子的人"],meaning:["Notice what the effort asks of your body and attention.","留意这份努力正在占用多少体力和注意力。"]},{name:["The distant roof","远处的屋顶"],meaning:["The place you want to reach can help you decide what to carry.","你想抵达的地方，能帮你决定什么值得带着。"]}],prompts:[["Which part of this load could you share, postpone, or set down?","这份重担里，哪一部分可以分担、推迟或放下？"],["What would make this commitment more sustainable next week?","怎样调整，能让你下周更从容地继续这项承诺？"]]},"wands-page":{sourcePage:190,upright:["You can learn something by giving a fresh interest a voice. The Page of Wands invites you to make a small attempt you can show or talk about. It can be unfinished. Notice what questions it brings back to you, and let one of them guide what you try next.","把一个新兴趣说出来，你可能就会多了解它一点。权杖侍从邀请你做个可以拿出来聊的小尝试，半成品也可以。留意它带回了哪些新问题，再挑其中一个决定接下来怎么试。"],traditional:["Waite links the Page with a messenger and describes a figure in the act of making a proclamation. The upright, leafy staff gives that announcement a visible point of attention.","韦特把侍从与传信者联系起来，描写了一个正要宣布消息的人。竖着的枝杖让这场表达有了一个看得见的焦点。"],symbols:[{name:["The upright wand","竖直的权杖"],meaning:["Bring a new interest into the open long enough to examine it.","把新兴趣带到眼前，好好看一会儿。"]},{name:["The turned face","转过去的脸"],meaning:["An attentive beginning can make room for a response.","带着注意力开口，也能留出听回应的空间。"]},{name:["The low dunes","低矮的沙丘"],meaning:["A simple setting leaves room for something to be tried.","简单的环境也可以容下一次尝试。"]}],prompts:[["What small first attempt could you show to someone you trust?","你可以把哪个小尝试拿给信任的人看看？"],["Which question would make this interest easier to explore?","问哪个问题，能让你更容易探索这份兴趣？"]]},"wands-knight":{sourcePage:188,upright:["Enthusiasm can take you a long way when it has somewhere to stop and check in. The Knight of Wands invites you to pick an action that matches your energy and your available time. Decide where you will pause to see what it changed before you ride on.","热情能带你走很远，也值得有个停下来看看结果的地方。权杖骑士邀请你选一个符合当下精力和时间的行动。继续向前前，先决定在哪里停一停，看看这个动作带来了什么。"],traditional:["Waite draws attention to the horse’s movement and associates the rider with departure and change of place. Within keeps the forward motion and gives the rider a stretch of open ground.","韦特提醒读者留意马的动作，并把骑士与出发、离开和更换地点联系起来。Within 保留了向前的势头，也给骑者留出一段开阔的路。"],symbols:[{name:["The lifting horse","扬起前身的马"],meaning:["Energy is available to start moving.","已经有了迈出一步的力气。"]},{name:["The angled staff","斜举的杖"],meaning:["Choose where to point that energy.","为这份力气选一个方向。"]},{name:["The open track","开阔的路"],meaning:["Pick a place to check in before the pace decides for you.","让速度决定下一步之前，先选好一个回看点。"]}],prompts:[["Where could you use your momentum today, and when will you pause to check it?","今天可以把势头用在哪里？什么时候停一下看看结果？"],["What small commitment fits the energy you actually have?","哪一个小承诺，和你现在真正有的精力相称？"]]},"wands-queen":{sourcePage:186,upright:["You can make room for your own energy and for the people around you. The Queen of Wands invites you to notice where a more direct expression of interest would help. Say what excites you, invite someone in, or make one choice that lets your work be seen on your terms.","你可以给自己的热情留地方，也给身边的人留地方。权杖王后邀请你看看，在哪件事上，更直接地表达兴趣会有帮助。说出让你兴奋的东西、邀请一个人加入，或按自己舒服的方式让作品被看见。"],traditional:["Waite’s account emphasizes a magnetic presence and describes the suit as one of living, leafy wands. The sunflower and cat in the traditional scene give Within two different ways to picture warmth and independence.","韦特谈到王后的吸引力，也把这套花色写成带叶、有生命力的权杖。传统画面里的向日葵和猫，让 Within 用两种不同的方式描绘温暖与独立。"],symbols:[{name:["The sunflower","向日葵"],meaning:["Warmth you can show in a form that feels like yours.","用自己自在的方式把温暖表达出来。"]},{name:["The cat","猫"],meaning:["A quiet presence that keeps its own pace.","安静地待在场上，也可以保有自己的节奏。"]},{name:["The leafy staff","长叶的杖"],meaning:["An interest that stays alive through attention.","持续留意的一份兴趣，可以一直有生机。"]}],prompts:[["How could you let yourself be seen in a way that feels like you?","你可以怎样让自己被看见，同时保持自己的样子？"],["Who might enjoy an invitation into something you care about?","你在乎的事情里，有没有谁可能乐意收到你的邀请？"]]},"wands-king":{sourcePage:184,upright:["Direction becomes useful when other people can understand it and act on it. The King of Wands invites you to state what matters, own one decision, and leave room for others to influence how the work gets done. A clear invitation can do more than another demand.","方向要能让别人理解，也能让人据此行动，才会真正有用。权杖国王邀请你说清在乎的是什么，承担一个决定，也让其他人参与决定怎么做。一句清楚的邀请，可以为合作留出空间。"],traditional:["Waite describes a flowering wand and stresses honesty and conscientiousness in this court card. Within uses the seated figure to ask what it takes to turn initiative into dependable leadership.","韦特描写了开花的权杖，也强调这张宫廷牌里的诚实与尽责。Within 借坐着的人发问，怎样才能把主动性变成别人可以依靠的带领？"],symbols:[{name:["The flowering wand","开花的权杖"],meaning:["A direction can grow through sustained attention.","一个方向能在持续的照料中长起来。"]},{name:["The solid seat","稳固的座椅"],meaning:["Take responsibility for the position you hold.","为自己所在的位置承担责任。"]},{name:["The small salamander","小小的火蜥蜴"],meaning:["Keep curiosity near the exercise of authority.","运用影响力时，也给好奇心留个位置。"]}],prompts:[["What direction could you state clearly while leaving others room to shape it?","你能怎样清楚表达方向，同时让别人参与塑造它？"],["What decision are you ready to take responsibility for?","你准备好为哪个决定承担责任？"]]}},h=a.Y.wands.map(e=>o(e,s[e.id])),l={"swords-ace":{sourcePage:265,upright:["When a situation feels tangled, try naming the one thing you know for sure. A clear sentence can make it easier to ask a fair question or decide what needs checking.","事情理不清时，先说出一件你确实知道的事。一句清楚的话，可以帮你问出更公平的问题，也能看见还有什么需要核实。"],traditional:["Waite describes a sword emerging from a cloud, with a crown around its point. He emphasizes force and triumph, including the intensity that can go with either.","韦特描写一柄从云中伸出的剑，剑尖穿过王冠。他强调力量和胜利，也提到这股力量可能有不同的去处。"],symbols:[{name:["The cloud","云层"],meaning:["The picture is still forming.","事情的全貌仍在浮现。"]},{name:["The straight blade","直立的剑"],meaning:["A distinction you can state plainly.","一个可以说清楚的区别。"]},{name:["The crown","王冠"],meaning:["Clarity comes with responsibility for how you use it.","想清楚之后，也要对自己的用法负责。"]}],prompts:[["What is the simplest accurate way to describe what happened?","怎么用最简单、准确的话描述发生的事？"],["What would help you check your first impression?","怎样核实你的第一印象？"]]},"swords-two":{sourcePage:263,upright:["Two priorities can both deserve your attention. Notice how much effort it takes to keep them balanced. There may be one piece of information you can seek before either has to give way.","两件事可能都值得你重视。留意维持平衡花了你多少力气。在必须作出取舍之前，也许还有一条信息可以先去确认。"],traditional:["Waite describes a blindfolded figure balancing two swords and reads the image as a qualified kind of equilibrium.","韦特描写了蒙眼的人平衡两柄剑，并将它理解为带有条件的均势。"],symbols:[{name:["The blindfold","眼罩"],meaning:["Some information is still out of view.","还有一些信息没有进入视野。"]},{name:["The balanced swords","平衡的双剑"],meaning:["Both sides require effort to hold.","两边都需要用力托住。"]},{name:["Water behind the seat","座位后的水面"],meaning:["Feelings can be present even when the surface looks still.","表面平静时，感受依然存在。"]}],prompts:[["Which uncertainty could you reduce this week?","这周，你可以减少哪一点不确定性？"],["What is the cost of keeping the decision suspended?","让决定一直悬着，会付出什么代价？"]]},"swords-three":{sourcePage:261,upright:["A painful change can be difficult to describe while it is still happening. Give yourself time to name what you miss and what you need now. Even one honest sentence may be enough for today.","有些改变带来的痛，正在经历时很难说清。给自己一点时间，想想你在怀念什么、眼下又需要什么。今天也许只需要说一句真心话。"],traditional:["Waite draws attention to the rain and the three blades piercing a heart. The meanings he records include separation and absence.","韦特着重描述了雨幕，以及穿过心形的三柄剑。他记下的牌义包括离别和缺席。"],symbols:[{name:["The heart","心形"],meaning:["Something mattered enough to leave a mark.","有件事足够重要，留下了痕迹。"]},{name:["The blades","剑刃"],meaning:["Several parts of an experience may hurt at once.","一段经历里，可能有几个地方同时令人难过。"]},{name:["The rain","雨幕"],meaning:["Grief can take up space for a while.","难过可以在生活里占据一会儿。"]}],prompts:[["Which part of the loss is hardest to put into words?","失去的哪一部分最难用语言说出来？"],["What would feel gentle and possible today?","今天有什么事，做起来温和又可行？"]]},"swords-four":{sourcePage:259,upright:["Try giving a problem a defined rest. You might close the tab, take a walk, or set a time to return tomorrow. A clear stopping point can make a pause easier to trust.","试着让一件事有明确的暂停时间。可以关掉页面、走一走，或者约定明天几点再回来。知道什么时候继续，暂停也会更踏实。"],traditional:["Waite describes a knight’s resting effigy with hands in prayer. Retreat, solitude and repose are among the meanings he lists.","韦特描写了躺卧祈祷的骑士雕像。他列出的牌义包括退隐、独处和休息。"],symbols:[{name:["The resting figure","静卧的人形"],meaning:["A deliberate break from effort.","主动放下努力片刻。"]},{name:["The three mounted swords","悬起的三柄剑"],meaning:["Urgent thoughts can wait outside the pause.","急切的念头可以先留在暂停之外。"]},{name:["The stone ledge","石台"],meaning:["A stable place to put something down.","一个可以安心放下东西的地方。"]}],prompts:[["What could you set aside until a specific time?","哪件事可以放到一个明确的时间再处理？"],["How will you know when you are ready to return?","你会怎样知道自己准备好回来了？"]]},"swords-five":{sourcePage:257,upright:["After a disagreement, the last word may matter less than what happens next. Look at what each person walked away with. You can decide whether to repair a part of the exchange or end it with a clear boundary.","争执过后，接下来怎么相处，往往比谁说了最后一句更重要。看看每个人带走了什么感受，再决定是修补这次交流的一部分，还是划清界限、到此为止。"],traditional:["Waite describes one figure collecting swords while two others leave the field. The scene brings the aftermath of conflict into view.","韦特描写一人收起剑，另外两人离开现场。画面把注意力留在冲突之后。"],symbols:[{name:["The collected blades","收起的剑"],meaning:["What one person claims after the encounter.","交锋结束后，一个人拿在手里的东西。"]},{name:["The departing figures","离开的人"],meaning:["Other people leave with their own account.","离开的人有他们各自的理解。"]},{name:["The fallen swords","落地的剑"],meaning:["The part of a dispute everyone can stop carrying.","争执里有些东西，可以一起放下。"]}],prompts:[["What did you hope to protect during the disagreement?","在这场争执里，你原本想保护什么？"],["What would a fair follow-up look like?","怎样接续这场对话，对双方都公平？"]]},"swords-six":{sourcePage:255,upright:["During a transition, aim for the next workable shore. Bring what will help you arrive and ask what can be left for another trip. Let someone share the practical work if they can.","过渡期里，可以先找一个够得着的岸。带上能帮你抵达的东西，看看什么可以留待下一趟。如果有人能帮忙，试着分出去一件具体的事。"],traditional:["Waite depicts a ferryman taking passengers across water. Journey, route and passage are central to the description.","韦特描写船夫载着乘客过水。旅程、路径与渡过，是这段描述的中心。"],symbols:[{name:["The ferry","渡船"],meaning:["A practical way to move through an in-between time.","一种度过过渡期的实际办法。"]},{name:["The passengers","乘客"],meaning:["It can help to make a crossing together.","有些路，一起走会容易些。"]},{name:["The far bank","对岸"],meaning:["A visible next place to aim for.","下一个看得见的落脚点。"]}],prompts:[["What would make the next stretch easier to cross?","什么能让接下来这一段更容易度过？"],["Who or what could carry a part of the load?","谁或什么能帮你分担一点？"]]},"swords-seven":{sourcePage:253,upright:["An indirect plan may feel easier in the moment. Ask what it depends on and what would happen if other people learned how it works. Consider whether you can be clearer about the part that affects them.","绕一点路的办法，当下可能更容易。问问自己，这个计划靠什么成立，别人知道它怎么运作之后又会怎样。牵涉到对方的那一部分，也许可以说得更清楚。"],traditional:["Waite describes a figure carrying five blades away from a camp, with two left behind. He records a mixture of intention, confidence and the possibility of a plan failing.","韦特描写一人从营地带走五柄剑，留下两柄。他记下谋划、信心，也提到计划可能落空。"],symbols:[{name:["The carried swords","被带走的剑"],meaning:["What a strategy is trying to secure.","一个策略想要拿到的东西。"]},{name:["The two left behind","留下的两柄剑"],meaning:["A plan has limits and leaves traces.","计划有边界，也会留下痕迹。"]},{name:["The distant camp","远处的营地"],meaning:["People affected by choices made out of sight.","看不到过程、却会受到影响的人。"]}],prompts:[["What assumption is your plan relying on?","你的计划依赖着哪个假设？"],["What can you say directly without giving away a needed boundary?","在守住必要界限的同时，哪些话可以直接说？"]]},"swords-eight":{sourcePage:251,upright:["When every option seems blocked, separate the barriers you can verify from the ones you are guessing about. Look for one small move you can make safely, or ask someone to help you see the space around you.","每条路似乎都被堵住时，把能确认的限制和自己推测的限制分开。找一个可以安心迈出的小动作，也可以请别人帮你看看身边还有哪些余地。"],traditional:["Waite describes a blindfolded, bound figure surrounded by swords. He characterizes the confinement as temporary.","韦特描写了蒙着眼、被束住的人，周围立着宝剑。他把这种受困形容为暂时的。"],symbols:[{name:["The loose binding","松垂的束带"],meaning:["One restriction may have room to change.","某个限制可能还有松动的余地。"]},{name:["The standing swords","立着的剑"],meaning:["Some obstacles deserve careful attention.","有些障碍需要认真对待。"]},{name:["The opening","前方的空隙"],meaning:["Start with the room that is available.","从实际存在的那点空间开始。"]}],prompts:[["Which limitation can you describe in observable terms?","哪项限制可以用看得见的事实来描述？"],["Who might help you see a choice you have missed?","谁能帮你看见一个遗漏的选项？"]]},"swords-nine":{sourcePage:249,upright:["A worry can fill a whole room at night. Put its most specific sentence on paper and decide whether it needs comfort, a question answered, or attention tomorrow. You can handle those needs separately.","夜里，一件担心的事仿佛能占满整个房间。把它最具体的那句话写下来，看看你此刻需要的是一点安慰、一个答案，还是留到明天再处理。这些需要可以分开照顾。"],traditional:["Waite describes a figure sitting on a bed in sorrow beneath a row of swords. The scene centers on distress as it is experienced by the person in it.","韦特描写一人坐在床上悲伤，上方排列着宝剑。画面把重点放在当事人正在经历的苦楚。"],symbols:[{name:["The bed","床榻"],meaning:["A private place where concerns can become vivid.","在私下独处时，担忧可能变得格外清楚。"]},{name:["The hands","双手"],meaning:["A moment to acknowledge how much you are holding.","承认此刻有多少东西压在心上。"]},{name:["The parallel swords","并排的剑"],meaning:["Thoughts that return in a familiar pattern.","以熟悉的方式一再回来的念头。"]}],prompts:[["What would you want a trusted person to understand about this worry?","你希望信任的人明白，这份担忧的哪一部分？"],["What can be left on the page until tomorrow?","有什么可以先留在纸上，等到明天？"]]},"swords-ten":{sourcePage:247,upright:["When an effort has reached its limit, take time to name what actually ended. Then look for the first ordinary thing that needs care. Restoring a routine can come before knowing what this ending means.","一份努力走到尽头时，先弄清究竟结束了什么。再看看眼下哪件平常的事最需要照料。可以先恢复一点日常，慢慢再理解这个结尾。"],traditional:["Waite’s scene shows a fallen figure beneath ten swords. He associates the image with pain and desolation. Within gives the horizon space alongside that weight.","韦特画面中的人倒在十柄剑下。他将它与痛苦和凄凉联系起来。Within 的画面也给远处的天际线留出空间。"],symbols:[{name:["The still figure","静止的人形"],meaning:["An effort has come to a stop.","一段努力停了下来。"]},{name:["The ten blades","十柄剑"],meaning:["The accumulated weight deserves acknowledgment.","累积的重量值得被承认。"]},{name:["The lit horizon","亮起的天际"],meaning:["The next day can begin with ordinary care.","新的一天可以从照料日常开始。"]}],prompts:[["What has ended, and what still needs your attention?","什么已经结束，什么还需要你照看？"],["What is one routine you would like to return to?","你想恢复哪一个日常习惯？"]]},"swords-page":{sourcePage:245,upright:["An interesting question can send your attention in every direction. Choose one observation to check and listen to the answer before preparing your reply. Curiosity works best when it has somewhere to land.","一个有意思的问题，可能一下子把注意力带向四面八方。先挑一条观察去核实，听完答案再准备回应。好奇心也需要一个落点。"],traditional:["Waite describes an alert young figure moving through rough ground with a sword in both hands. He links the card with vigilance and examination.","韦特描写一位警觉的年轻人双手持剑，走过崎岖地面。他把这张牌与警觉和查验联系起来。"],symbols:[{name:["The sword held high","高举的剑"],meaning:["Attention ready to engage.","随时准备投入的注意力。"]},{name:["The gusts","阵风"],meaning:["Signals that may change as you watch.","观察时仍在变化的讯息。"]},{name:["The uneven ground","不平的地面"],meaning:["Keep an eye on what is directly in front of you.","也留意眼前脚下的事。"]}],prompts:[["Which question would help you learn something genuinely new?","哪个问题能让你真的了解到一点新东西？"],["What have you heard, and what have you checked yourself?","哪些是听说的，哪些是你亲自核实的？"]]},"swords-knight":{sourcePage:243,upright:["A quick response can be useful when the goal is clear. Before setting off, check that your first action serves that goal and that the people affected have time to keep up.","目标清楚时，快速回应可以帮上忙。出发前先确认，第一步是否真能推动目标，受影响的人是否有时间跟上。"],traditional:["Waite presents a rider charging with a sword. Skill and bravery appear alongside hostility and resistance in his account.","韦特描写了持剑疾驰的骑士。他同时记下本领、勇气，以及敌意和抵抗。"],symbols:[{name:["The forward blade","向前的剑"],meaning:["A response already gathering speed.","已经开始加速的回应。"]},{name:["The running horse","奔跑的马"],meaning:["Momentum can carry a decision farther than intended.","势头起来后，决定可能走得比预想更远。"]},{name:["The wind marks","风的线条"],meaning:["Notice how much the pace is shaping what you see.","留意速度怎样影响你的观察。"]}],prompts:[["What deserves a quick response, and what needs a check first?","什么值得迅速回应，什么需要先核实？"],["Whose pace should you account for before acting?","行动前，你需要考虑谁的节奏？"]]},"swords-queen":{sourcePage:241,upright:["You can be candid and leave room for someone else to answer. Try stating the boundary in one sentence, then naming the part you are still willing to discuss.","你可以坦率，也可以给对方留下回应的空间。先用一句话说清界限，再说说还有哪一部分你愿意继续讨论。"],traditional:["Waite describes an upright sword, an extended hand and an expression shaped by sorrow. Within’s scene keeps both the firm line and the open gesture.","韦特描写了直立的剑、伸出的手，以及经历过悲伤的神情。Within 的画面保留了坚定的线条和开放的手势。"],symbols:[{name:["The upright sword","直立的剑"],meaning:["A boundary that can be communicated plainly.","一道可以直接说清的界限。"]},{name:["The open hand","摊开的手"],meaning:["An invitation to answer.","给对方回应的机会。"]},{name:["The high seat","高背座椅"],meaning:["Take enough space to speak from experience.","给自己足够的空间，从经验出发说话。"]}],prompts:[["What boundary would benefit from a direct sentence?","哪道界限值得你直接说清？"],["What can you still be curious about in this conversation?","这场谈话里，你还可以对什么保持好奇？"]]},"swords-king":{sourcePage:239,upright:["A judgment becomes easier to trust when others can follow the reasoning. Name the evidence, the standard you are applying, and what might make you reconsider.","别人能跟上你的理由时，判断就更容易被信任。说清依据是什么、采用什么标准，以及什么情况会让你重新考虑。"],traditional:["Waite connects the seated sword bearer with judgment and the authority of an office. The scene gives that authority a visible weight.","韦特把端坐持剑的人与判断、职位赋予的权威相连。画面让权力带有可见的重量。"],symbols:[{name:["The sword at the center","居中的剑"],meaning:["A rule applied openly.","摆在明处、可以讨论的规则。"]},{name:["The symmetrical throne","对称的王座"],meaning:["Consistency across people and cases.","面对不同的人和情形，保持一致。"]},{name:["The steps","台阶"],meaning:["Decisions have effects beyond the seat of judgment.","决定的影响会走下王座，抵达别处。"]}],prompts:[["Could someone else reproduce your reasoning from the evidence you have?","用你掌握的证据，别人能复述你的判断过程吗？"],["What would be a fair reason to change your mind?","什么理由出现时，改变想法才算公平？"]]}},d=a.Y.swords.map(e=>o(e,l[e.id])),c={"pentacles-ace":{sourcePage:293,upright:["A possibility gets easier to work with when you give it a place and a time. Take stock of what is already available, then choose one thing you could make, learn, or set up with it.","给一个可能性安排具体的时间和地方，它就更容易落地。盘点手头已经有的东西，再挑一件可以借它做出来、学起来或安排好的事。"],traditional:["Waite depicts a hand holding a pentacle out of a cloud. His account associates the card with contentment and favorable material conditions.","韦特描写一只手从云中伸出，托着一枚星币。他把这张牌与满足感、良好的物质条件联系起来。"],symbols:[{name:["The offered coin","递出的星币"],meaning:["A resource you can put to use.","一份可以用起来的资源。"]},{name:["The garden gate","花园的门"],meaning:["A concrete point of entry.","一个具体的入口。"]},{name:["The path","小路"],meaning:["Something grows once you start tending it.","着手照料后，事情才开始生长。"]}],prompts:[["What do you already have that would let you begin?","手头已经有什么，足够让你开始？"],["Where and when could you take a first step?","你可以在什么时候、什么地方走出第一步？"]]},"pentacles-two":{sourcePage:291,upright:["When several demands change at once, look for a rhythm you can actually sustain. See which task can be made smaller, moved, or shared. Your schedule can move with you.","几项要求同时变化时，找一种你实际能维持的节奏。看看哪件事可以缩小、挪时间，或分给别人一点。安排也可以跟着你调整。"],traditional:["Waite depicts a dancer with two pentacles joined by a looping cord. He records both playfulness and the bustle that comes with obstacles.","韦特描写舞者手持两枚星币，由一条环绕的绳子相连。他记下轻快玩乐，也记下受阻时的忙乱。"],symbols:[{name:["The looping cord","环形绳带"],meaning:["Attention can move back and forth.","注意力可以在两件事之间来回。"]},{name:["The two coins","两枚星币"],meaning:["Each demand has its own weight.","每一项要求都有自己的分量。"]},{name:["The changing waves","起伏的波浪"],meaning:["A schedule has to make room for changing conditions.","安排需要给变化留出余地。"]}],prompts:[["Which two things are you trying to keep in motion?","你现在想同时推进哪两件事？"],["What would make your week a little easier to adjust?","怎样能让这一周的安排更容易调整一点？"]]},"pentacles-three":{sourcePage:289,upright:["A skill becomes useful to a group when people can see how it fits. Show a small part of your work, ask how it meets the shared goal, and listen for what another person knows better.","别人能看见一项本领怎么接进整体，它就能帮上团队。拿出一小部分成果，问问它是否符合共同目标，也听听别人更熟悉哪一块。"],traditional:["Waite shows a sculptor working in a monastery. He distinguishes the practiced craftsperson here from the learner of the Eight.","韦特描写雕刻师在修道院工作，并把这里能承担任务的工匠和星币八中的学习者作了对照。"],symbols:[{name:["The arch","拱顶"],meaning:["A whole structure that depends on its pieces.","整体由各个部分共同支撑。"]},{name:["The workbench","工作台"],meaning:["A visible place to demonstrate a skill.","一个能把本领展示出来的地方。"]},{name:["The plans","图纸"],meaning:["A shared reference for making decisions together.","一起作决定时，大家都可以看的依据。"]}],prompts:[["What part of a shared project could you make easier to see?","共同做的事情里，哪一部分可以让大家看得更清楚？"],["Whose expertise would make this work better?","谁的经验能让这件事做得更好？"]]},"pentacles-four":{sourcePage:287,upright:["Holding on can be an understandable response to uncertainty. Work out how much you need in order to feel steady. You may find a small amount of time, space, or effort you can let circulate again.","不确定时，想把手里的东西攥紧很自然。先弄清什么是让你安心的底线。也许有一点时间、空间或力气，可以重新流动起来。"],traditional:["Waite describes a crowned figure holding one pentacle, with another above and two beneath the feet. His account emphasizes keeping what is already possessed.","韦特描写戴王冠的人抱住一枚星币，头顶一枚，脚下两枚。他的解释强调守住已有的东西。"],symbols:[{name:["The coin held close","抱紧的星币"],meaning:["Something that feels important to secure.","一件你觉得必须守住的东西。"]},{name:["The coins underfoot","脚下的两枚星币"],meaning:["Security can also make movement harder.","稳定有时也会让移动变难。"]},{name:["The city walls","城墙"],meaning:["A boundary with an inside and an outside.","一道分出内外的边界。"]}],prompts:[["What are you protecting, and how much protection does it need?","你在保护什么，它究竟需要多少保护？"],["What could you share or loosen a little and still feel secure?","什么可以稍微分享或放松一点，同时还让你安心？"]]},"pentacles-five":{sourcePage:285,upright:["When conditions are difficult, make the need specific. Warmth, company, a ride, and help making a call are different requests. There may be one door you can knock on today.","处境艰难时，先把需要说具体。想取暖、找个人陪伴、搭一趟车，或请人帮忙打电话，是不同的请求。今天也许有一扇门可以先敲一敲。"],traditional:["Waite shows two people outside a lit window in a snowstorm. Material hardship is central to his account, alongside other readings that he records.","韦特描写雪中两人走过亮着灯的窗户。物质上的艰难是他解读的中心，他也记录了其他传统解释。"],symbols:[{name:["The snow","落雪"],meaning:["The conditions themselves can make a task harder.","有时是环境本身让事情变难。"]},{name:["The companions","同行的人"],meaning:["Company can matter before there is a solution.","解决办法出现之前，陪伴已经有意义。"]},{name:["The lit window","亮着的窗"],meaning:["A place to look for possible support.","一个可以寻找支持的地方。"]}],prompts:[["What help would make the biggest difference today?","今天哪一种帮助会带来最大的差别？"],["Who could you ask for one specific thing?","你可以向谁提出一个具体的请求？"]]},"pentacles-six":{sourcePage:283,upright:["Before giving or accepting help, make room to talk about what would actually be useful. A clear offer with an easy way to decline can leave both people with more choice.","给出或接受帮助前，先留一点空间谈谈什么真的有用。把能提供的帮助说清，也让对方可以轻松拒绝，双方都会多一点选择。"],traditional:["Waite describes a merchant weighing money and distributing it to others. His account draws attention to gifts and the act of giving.","韦特描写商人称量钱币并分给别人。他把注意力放在赠予和给予的动作上。"],symbols:[{name:["The scales","天平"],meaning:["Consider how the exchange feels from each side.","想想交换在双方看来各是什么样。"]},{name:["The offered coins","递出的星币"],meaning:["Help takes a form someone can actually use.","帮助有具体的形式，才有机会派上用场。"]},{name:["The open hands","伸开的手"],meaning:["Receiving is an active part of the exchange.","接受也是交换中主动的一部分。"]}],prompts:[["What kind of support would feel fair and useful here?","在这里，怎样的支持既公平又有用？"],["How can someone ask for more or say they have enough?","怎样让对方能说自己还需要一点，或已经够了？"]]},"pentacles-seven":{sourcePage:281,upright:["When work grows slowly, pause where you can see it clearly. Look for a concrete sign of progress and one change you might make to how you tend it. Give yourself a date to check again.","事情长得慢时，找个能看清它的地方停一停。看一个具体的进展迹象，再想一处可以调整的照料方式。给自己定个日子回来看看。"],traditional:["Waite describes a person leaning on a tool and looking at a plant bearing seven pentacles. He records divergent meanings, many concerned with practical affairs.","韦特描写一人倚着工具，望向挂着七枚星币的植物。他记下多种解释，其中不少与实际事务有关。"],symbols:[{name:["The growing plant","生长的植物"],meaning:["Some results develop on their own timetable.","有些成果有自己的生长时间。"]},{name:["The resting tool","歇下的工具"],meaning:["Observation can be part of the work.","停下来观察，也是工作的一部分。"]},{name:["The seven coins","七枚星币"],meaning:["Look for what has accumulated so far.","看看迄今已经积累了什么。"]}],prompts:[["What would count as progress at your next check-in?","下次回看时，什么可以算作进展？"],["Which effort could you change before adding more of it?","继续投入前，哪一种做法可以先调整？"]]},"pentacles-eight":{sourcePage:279,upright:["Pick one small part of a craft and practice it with attention. Compare a later attempt with an earlier one and name the difference you can actually see.","挑出一门手艺中很小的一部分，专心练一练。把新一次尝试和早一点的摆在一起，说出自己确实看得到的变化。"],traditional:["Waite shows a stoneworker at work with completed pieces on display. He connects the scene with skill, employment and the early stages of craftsmanship.","韦特描写石匠工作，旁边摆着已经完成的作品。他把画面与技艺、工作和学艺的早期阶段联系起来。"],symbols:[{name:["The chisel","凿子"],meaning:["A specific tool for a specific improvement.","用具体工具改进具体的一处。"]},{name:["The unfinished piece","未完成的作品"],meaning:["The attempt that has your attention now.","此刻正在专注的这一次尝试。"]},{name:["The displayed coins","摆出的星币"],meaning:["A record of what repeated work has made possible.","反复练习已经带来的变化。"]}],prompts:[["Which part of the work would repay focused repetition?","工作里的哪一小段值得专门重复练习？"],["How could you keep a visible record of what you learn?","怎么把学到的变化记下来，让它看得见？"]]},"pentacles-nine":{sourcePage:277,upright:["Take some time to enjoy a resource or habit you helped build. Notice which conditions let you use it on your own terms and which ones you want to maintain.","留一点时间享用你参与建立的资源或习惯。看看哪些条件让你能按自己的方式使用它，又有哪些条件值得继续维护。"],traditional:["Waite shows a figure with a bird on the wrist among abundant vines. His account includes discernment, accomplishment and security.","韦特描写一人站在丰茂的葡萄藤间，手腕上立着鸟。他记下辨别力、成就和安稳。"],symbols:[{name:["The vines","藤蔓"],meaning:["Comfort can take seasons of care to grow.","安稳可能来自好几个季节的照料。"]},{name:["The perched bird","停在腕上的鸟"],meaning:["Trust and attention make freedom easier to hold.","信任与照料能让自主更容易维持。"]},{name:["The garden path","园中的小径"],meaning:["A place you can move through at your own pace.","一个能按自己步速走过的地方。"]}],prompts:[["What can you enjoy today because of work you did earlier?","因为从前做过的努力，你今天可以享受什么？"],["Which part of your independence do you want to keep tending?","你的自主生活里，哪一部分还想继续照料？"]]},"pentacles-ten":{sourcePage:275,upright:["Consider what you received from people who were here before you. A routine, a piece of knowledge, or a place of welcome can be worth passing on. Decide how to make one of those things easier for someone else to use.","想想你从先来的人那里接过了什么。一项习惯、一点知识，或者一个愿意接纳人的地方，都可能值得传下去。选其中一件，让后来的人更容易用上它。"],traditional:["Waite describes several generations and their dogs gathered beneath an arch. He connects the scene with household, family history and accumulated resources.","韦特描写几代人和狗聚在一道拱门附近。他把画面与家园、家族记忆和累积下来的资源联系起来。"],symbols:[{name:["The archway","拱门"],meaning:["A place that can welcome people over time.","长久以来可以接纳人的地方。"]},{name:["The elder and child","长者与孩子"],meaning:["Knowledge can travel between generations.","知识可以在不同世代之间传递。"]},{name:["The coins above the doorway","门上排列的星币"],meaning:["The traces of what has been built together.","共同建立的东西留下的痕迹。"]}],prompts:[["What do you want to pass on in a form someone else can use?","你想用别人能用得上的方式，传下什么？"],["Which inherited habit would you choose to adapt?","哪一种传下来的习惯，你想把它改一改？"]]},"pentacles-page":{sourcePage:273,upright:["Start learning through something you can hold, make, or observe. Keep the first assignment small and give yourself one question you can answer by the end of it.","从一件能拿在手里、做出来或亲眼观察的东西开始学。把第一项练习定小一点，留一个做完就能回答的问题。"],traditional:["Waite depicts a young figure studying a pentacle above raised hands. Application, study and reflection appear among his readings.","韦特描写年轻人凝视举起的双手上方的一枚星币。他记下的牌义包括用心钻研、学习和思考。"],symbols:[{name:["The held-up coin","举起的星币"],meaning:["A concrete thing to study closely.","一件可以仔细研究的实物。"]},{name:["The lifted hands","举起的双手"],meaning:["Readiness to work with what you learn.","准备把学到的东西用起来。"]},{name:["The open field","开阔的田野"],meaning:["Room to make an early attempt.","给第一次尝试留出的空间。"]}],prompts:[["What could you make or examine to understand this better?","做一个什么东西，或观察什么，能帮你理解得更好？"],["What question could one short practice session answer?","一次短练习能回答哪个问题？"]]},"pentacles-knight":{sourcePage:271,upright:["Choose a pace you could repeat on an ordinary day. Name what will get done, when it will happen, and what you will do if you miss a day.","选一种在普通日子里也能重复的步速。说清要完成什么、什么时候做，以及漏了一天后怎么接回来。"],traditional:["Waite describes a rider on a slow, sturdy horse, displaying a pentacle. He associates the scene with practical service and responsibility.","韦特描写骑士骑着缓慢而结实的马，展示手中的星币。他把画面与切实的服务和责任联系起来。"],symbols:[{name:["The planted hooves","稳稳落地的马蹄"],meaning:["A pace that stays possible under ordinary conditions.","平常条件下也能维持的步速。"]},{name:["The offered coin","展示的星币"],meaning:["A specific task you can be responsible for.","一件你能负责到底的具体事。"]},{name:["The furrows","田垄"],meaning:["Repeated passes make progress visible.","重复走过，进展就有了痕迹。"]}],prompts:[["Which commitment would benefit from a dependable rhythm?","哪项承诺需要一种可靠的节奏？"],["How could you resume it easily after an interruption?","中断后，怎样能比较容易地接回来？"]]},"pentacles-queen":{sourcePage:269,upright:["Look for one physical condition you could make kinder for yourself or someone else. A place to sit, food ready at the right time, or a little space to work can make care tangible.","看看能不能把某个实际条件变得更体贴一点，让自己或别人用得上。一个能坐下的地方、一份准时备好的饭，或一点可以安心做事的空间，都能让关心落到实处。"],traditional:["Waite describes a seated figure contemplating the pentacle. He records generosity, security and freedom among the card’s meanings.","韦特描写端坐的人凝视星币。他记下的牌义包括慷慨、安稳和自由。"],symbols:[{name:["The coin in the lap","膝上的星币"],meaning:["Care can attend to a concrete need.","照料可以落到具体的需要上。"]},{name:["The leafy canopy","枝叶的遮蔽"],meaning:["A setting can offer shelter and ease.","环境也能提供遮护和舒适。"]},{name:["The rabbit","兔子"],meaning:["Leave a little space for the lives around you.","给周围的生命留一点地方。"]}],prompts:[["What would make this space easier to live or work in?","怎样能让这里更适合生活或工作？"],["What form of care could you give regularly without exhausting yourself?","哪种照料可以经常给出，同时不把自己耗尽？"]]},"pentacles-king":{sourcePage:267,upright:["When you look after shared resources, ask who can use them and how decisions get made. A simple routine or a clear record can make stewardship easier for the next person to carry.","照管共享资源时，可以问问谁能使用它、决定又是怎么作出的。一套简单的流程或一份清楚的记录，能让下一个人更容易接手。"],traditional:["Waite notes the bull heads on the throne and the pentagram on the suit’s emblem. He connects the card with practical judgment and capability.","韦特提到王座上的牛首，以及这组牌徽记上的五芒星。他把这张牌和务实的判断与能力联系起来。"],symbols:[{name:["The bull heads","牛首纹样"],meaning:["The patient strength behind a lasting structure.","能让一个结构持久的耐心和力量。"]},{name:["The cultivated vines","栽培的藤蔓"],meaning:["Resources grow through continuing attention.","资源需要持续照看才能积累。"]},{name:["The coin at the center","中央的星币"],meaning:["Something held in trust for more than one use.","手里照管着、可以用于多处的一份资源。"]}],prompts:[["What resource are you responsible for making easier to use?","你负责让哪项资源变得更好用？"],["What would help another person take over its care?","什么能帮别人接手照管它？"]]}},u=a.Y.pentacles.map(e=>o(e,c[e.id])),m={"the-fool":{imagePath:"/cards/the-fool.svg",keywords:["Beginnings","Openness","Possibility"],uprightMeaning:"There is a kind of wisdom in beginning before you have every answer. The Fool invites you to notice where curiosity is quietly asking for more room. You can take a small, considered step into something unfamiliar without needing to map the whole journey.",traditionalInterpretation:"Often placed at the beginning of the Major Arcana, the Fool represents a traveler entering the unknown. Traditionally associated with spontaneity, innocence, and risk, the card holds both the joy of possibility and the need to pay attention to the ground beneath your feet.",symbolism:[{element:"The open horizon",description:"A future that has not yet been defined; possibility rather than a promise."},{element:"The small traveler",description:"Beginning with what you have, without carrying every old expectation."},{element:"The cliff",description:"The meeting point of freedom and responsibility. A leap is still a choice."}],reflectionPrompts:["What would you explore if you did not need to be good at it immediately?","What is one small beginning you could make today?"]},"the-magician":{imagePath:"/cards/the-magician.svg",keywords:["Intention","Resourcefulness","Agency"],uprightMeaning:"Your attention, experience, and everyday tools may already be enough to begin. The Magician asks how you might bring an intention into the world through a concrete action. Resourcefulness often starts with recognizing what is already within reach.",traditionalInterpretation:"The Magician connects intention with material action. In traditional decks, the four suit emblems rest on a table, suggesting a range of available resources. The card can signify skill and initiative, while also inviting honesty about the difference between appearing capable and doing the work.",symbolism:[{element:"The raised hand",description:"An idea seeking expression through deliberate action."},{element:"The table",description:"A place to gather your resources and turn intention into practice."},{element:"The infinity sign",description:"The ongoing exchange between learning, making, and beginning again."}],reflectionPrompts:["Which resource are you overlooking because it already feels ordinary?","What action would make your intention visible?"]},"the-high-priestess":{imagePath:"/cards/the-high-priestess.svg",keywords:["Stillness","Intuition","Inner knowing"],uprightMeaning:"Some thoughts become clearer when you stop asking them to speak immediately. The High Priestess makes room for observation, uncertainty, and the knowledge you have not yet put into words. Listen inward, then let experience help you test what you hear.",traditionalInterpretation:"Seated between two pillars, the High Priestess traditionally guards a threshold of knowledge. Her associations with the moon, hidden texts, and a veil suggest that understanding can be partial and gradual. Intuition is an invitation to investigate, not an exemption from questioning.",symbolism:[{element:"The two pillars",description:"Different perspectives held together without rushing to choose a side."},{element:"The crescent moon",description:"The changing visibility of what we feel and know."},{element:"The veil",description:"A reminder that not every part of a situation is currently visible."}],reflectionPrompts:["What have you noticed but not yet allowed yourself to name?","What might become clearer if you paused before deciding?"]},"the-empress":{imagePath:"/cards/the-empress.svg",keywords:["Care","Creativity","Abundance"],uprightMeaning:"Something worthwhile may need tending rather than more pressure. The Empress invites you to notice the conditions that let life and creativity grow: rest, attention, nourishment, and room to experiment. Care can be practical. Ask what you could support consistently, and whether you are allowing yourself to receive the same kindness you offer others.",traditionalInterpretation:"The Empress is commonly associated with nature, fertility, and creative abundance. A crown, growing grain, and a comfortable seat place her in a landscape of life taking form. Here, fertility is read broadly as the capacity to nurture ideas, relationships, and everyday life, rather than a claim about pregnancy or a prescribed gender role.",symbolism:[{element:"Growing grain",description:"The result of patient attention and conditions that support growth."},{element:"The crown of stars",description:"Care connected with a world larger than any one person."},{element:"The resting seat",description:"Receiving comfort as well as providing it."}],reflectionPrompts:["What in your life would grow with care rather than pressure?","Where could you let yourself receive support?"]},"the-emperor":{imagePath:"/cards/the-emperor.svg",keywords:["Structure","Boundaries","Responsibility"],uprightMeaning:"A clear boundary or a dependable routine can create room to breathe. The Emperor asks which structures support your values and which ones have become rigid habits. Consider one responsibility you can own, one limit you can state, or one small system that would help you act with steadiness rather than trying to control every outcome.",traditionalInterpretation:"Traditionally pictured on a stone throne, the Emperor represents authority, order, and the material foundations of a community. The card can invite leadership and responsibility, while also raising questions about inflexibility and whose needs a structure serves. Authority can be exercised through clarity and care rather than dominance.",symbolism:[{element:"The stone throne",description:"A stable foundation, which can also become difficult to change."},{element:"The mountains",description:"The endurance and limits of established structures."},{element:"The scepter",description:"Responsibility for how influence is used."}],reflectionPrompts:["Which boundary would make your freedom more sustainable?","What are you responsible for, and what are you trying to control?"]},"the-hierophant":{imagePath:"/cards/the-hierophant.svg",keywords:["Tradition","Learning","Belonging"],uprightMeaning:"You do not have to build every understanding alone. The Hierophant invites you to look at the teachings, communities, and inherited rules that shape your choices. Some offer useful support; others deserve a question. Seek a teacher or shared practice that welcomes your curiosity, and notice when belonging asks you to silence your own judgment.",traditionalInterpretation:"The Hierophant is associated with religious teaching, institutions, and the transmission of shared knowledge. The seated teacher and crossed keys suggest access to an established tradition. A modern reflection can hold both the value of learning from others and the need to examine a tradition’s assumptions.",symbolism:[{element:"The teacher",description:"Knowledge passed between people rather than discovered in isolation."},{element:"The crossed keys",description:"Different ways of entering a body of understanding."},{element:"The two students",description:"Learning, community, and the influence of shared expectations."}],reflectionPrompts:["Which inherited belief still serves you, and which needs another look?","Who helps you think more clearly without asking you to stop questioning?"]},"the-lovers":{imagePath:"/cards/the-lovers.svg",keywords:["Connection","Values","Choice"],uprightMeaning:"A meaningful connection often asks you to show up with more honesty. The Lovers can be a lens on relationships, but also on choices that bring your actions closer to your values. Notice what you are consenting to, what you are leaving unsaid, and whether a decision makes room for both connection and a distinct sense of self.",traditionalInterpretation:"The Lovers is connected with relationship, attraction, and consequential choice. In the Rider–Waite–Smith imagery, two figures stand beneath an angel, with contrasting trees behind them. The card can be explored as a question of alignment and mutual recognition, without treating it as a promise of a particular romantic outcome.",symbolism:[{element:"The two figures",description:"Meeting another person while remaining responsible for your own choices."},{element:"The angel above",description:"An invitation to consider values larger than immediate desire."},{element:"The two trees",description:"Different experiences and perspectives brought into relationship."}],reflectionPrompts:["What choice would bring your actions closer to what you value?","Where would greater honesty make a connection more mutual?"]},"the-chariot":{imagePath:"/cards/the-chariot.svg",keywords:["Direction","Commitment","Coordination"],uprightMeaning:"Movement becomes easier when your competing priorities have a direction to share. The Chariot invites a deliberate commitment, not a demand to push through every limit. Ask where your energy is going, what is pulling it in different directions, and what support would help you move steadily toward a goal you have actually chosen.",traditionalInterpretation:"The Chariot traditionally concerns determination, directed will, and movement. Two contrasting creatures suggest forces that need coordination. Its image of forward motion can also prompt a useful question: are you steering toward something meaningful, or relying on momentum because stopping would require a decision?",symbolism:[{element:"The contrasting sphinxes",description:"Different drives that can work together without becoming identical."},{element:"The canopy of stars",description:"A wider frame for the direction you choose."},{element:"The wheels",description:"Commitment becoming movement through ordinary, repeated action."}],reflectionPrompts:["Which goal deserves your energy, rather than simply having your momentum?","What competing needs could you coordinate instead of suppressing?"]},strength:{imagePath:"/cards/strength.svg",keywords:["Courage","Gentleness","Patience"],uprightMeaning:"Strength does not always feel forceful. It may be the patience to stay with an uncomfortable feeling, the courage to speak plainly, or the restraint to respond without escalating. This card invites a relationship with your instincts that includes both compassion and boundaries. You can acknowledge a strong feeling without letting it make every decision.",traditionalInterpretation:"In this tradition, Strength shows a person attending calmly to a lion. The image brings courage together with gentleness and sustained attention. It can be read as a conversation between instinct and awareness, rather than a demand to defeat an unruly part of yourself.",symbolism:[{element:"The lion",description:"Vitality, appetite, anger, and other powerful instincts."},{element:"The gentle hands",description:"Influence through attention rather than unnecessary force."},{element:"The infinity sign",description:"An ongoing practice of meeting yourself with steadiness."}],reflectionPrompts:["What would courage look like if it did not require you to be harsh?","Which feeling could you acknowledge without immediately acting on it?"]},"the-hermit":{imagePath:"/cards/the-hermit.svg",keywords:["Solitude","Discernment","Inner light"],uprightMeaning:"A little distance can help you hear your own thoughts again. The Hermit offers an intentional pause from other people’s urgency and expectations. Solitude can be a place to clarify what matters, before returning to the world with a steadier sense of direction.",traditionalInterpretation:"The Hermit carries a lantern through a mountainous landscape. Traditionally connected with study, reflection, and the search for wisdom, this card asks for patient discernment. Its invitation is to seek useful solitude while remaining aware of when withdrawal becomes avoidance.",symbolism:[{element:"The lantern",description:"Enough light for the next step, even when the whole path is unknown."},{element:"The mountain",description:"Perspective gained slowly through experience and effort."},{element:"The walking staff",description:"The habits and supports that make independent exploration possible."}],reflectionPrompts:["Which of your priorities still matters when nobody else is watching?","What is the difference between the solitude you need and the connection you miss?"]},"wheel-of-fortune":{imagePath:"/cards/wheel-of-fortune.svg",keywords:["Change","Cycles","Adaptability"],uprightMeaning:"Not every change is a verdict on your effort or worth. The Wheel invites you to distinguish what you can influence from what is moving around you. Look for a pattern without assuming it must repeat forever. A useful response may be a small adjustment, a backup plan, or the willingness to notice an opening you did not arrange.",traditionalInterpretation:"The turning wheel is traditionally associated with changing circumstances and the rise and fall of fortune. Figures around it suggest different positions within the same movement. For this experience, the image offers a way to think about uncertainty and adaptation, rather than a claim that a fixed fate is directing events.",symbolism:[{element:"The wheel",description:"Conditions that change even when we wish they would stay still."},{element:"The rising and falling figures",description:"A position can be temporary rather than a permanent identity."},{element:"The surrounding witnesses",description:"The possibility of observing a pattern before responding."}],reflectionPrompts:["What is changing that you could respond to without taking it as a judgment of yourself?","Which small adjustment is within your control?"]},justice:{imagePath:"/cards/justice.svg",keywords:["Fairness","Accountability","Clarity"],uprightMeaning:"A clearer view may require separating what happened, what you intended, and what the effects were. Justice invites you to consider evidence, consequences, and the perspectives of people affected by a choice. Accountability can make repair possible. It is also worth asking whether you are judging yourself by a standard you would never impose on someone else.",traditionalInterpretation:"Justice is traditionally pictured with scales and an upright sword. The image joins careful weighing with the need to make a distinction or decision. It raises questions of responsibility and fairness without suggesting that every difficult circumstance is deserved or that the world always distributes outcomes justly.",symbolism:[{element:"The scales",description:"Weighing evidence and perspectives before reaching a conclusion."},{element:"The upright sword",description:"The clarity and responsibility involved in making a distinction."},{element:"The balanced seat",description:"A pause to consider the basis of a judgment."}],reflectionPrompts:["What evidence or perspective would make your judgment more fair?","What would taking responsibility look like without turning it into self-punishment?"]},"the-hanged-man":{imagePath:"/cards/the-hanged-man.svg",keywords:["Perspective","Pause","Letting go"],uprightMeaning:"When more effort keeps producing the same answer, a different angle may offer more than another push. The Hanged Man suggests a willing pause: set down one familiar assumption and see what changes. You do not have to solve everything from the position you started in.",traditionalInterpretation:"The suspended figure is traditionally shown with a calm expression and a halo. The image has been read as voluntary surrender, a reversal of ordinary priorities, and understanding gained through stillness. A pause can be meaningful without making suffering a virtue.",symbolism:[{element:"The inverted figure",description:"The familiar world viewed from an unfamiliar position."},{element:"The halo",description:"A moment of recognition that can arrive when striving pauses."},{element:"The living tree",description:"Life continuing even while visible progress seems suspended."}],reflectionPrompts:["Which assumption would you need to release to see another possibility?","How might this situation look to someone whose priorities differ from yours?"]},death:{imagePath:"/cards/death.svg",keywords:["Endings","Transition","Release"],uprightMeaning:"Something can have mattered and still be ready to end. Death invites you to notice a role, expectation, or arrangement that no longer fits. Letting go may include grief as well as relief; neither needs to be rushed. Consider what you want to honor, what you can release, and what support would make a transition more humane.",traditionalInterpretation:"The Death card is widely read as an image of endings and transformation. Its rider, banner, and distant rising sun place an ending within a larger cycle. In this app it is a symbolic prompt about change; it does not predict a death, illness, or other literal event.",symbolism:[{element:"The rider",description:"Change that moves beyond a familiar role or arrangement."},{element:"The white flower on the banner",description:"The possibility of new life within a process of release."},{element:"The rising sun",description:"Continuity beyond the edge of what is currently familiar."}],reflectionPrompts:["What could you let end while still honoring what it gave you?","What support would help you move through a transition at your own pace?"]},temperance:{imagePath:"/cards/temperance.svg",keywords:["Integration","Balance","Experiment"],uprightMeaning:"You may not have to choose between two needs as completely as it first appears. Temperance invites a patient experiment in proportion: a different pace, a smaller dose, or a rhythm that makes room for both effort and recovery. Balance is something to adjust in practice, rather than an ideal state you must achieve once and hold forever.",traditionalInterpretation:"Temperance shows a figure pouring between two vessels, often with one foot on land and one in water. It traditionally concerns moderation and the combining of different elements. The image can suggest active integration: trying, observing the result, and adjusting, rather than remaining neutral about everything.",symbolism:[{element:"The two vessels",description:"An exchange between different resources, experiences, or needs."},{element:"Land and water",description:"Practical grounding and emotional experience held together."},{element:"The distant path",description:"A direction approached through patient adjustments."}],reflectionPrompts:["Which two needs could you make room for in a different proportion?","What small experiment would help you find a more sustainable rhythm?"]},"the-devil":{imagePath:"/cards/the-devil.svg",keywords:["Attachment","Patterns","Agency"],uprightMeaning:"A habit or expectation can become so familiar that its costs are hard to notice. The Devil invites a curious look at what keeps you attached: comfort, fear, approval, or a real constraint that needs support. Recognizing a pattern does not make change easy, but it can reveal one place where you have more choice than you thought.",traditionalInterpretation:"The Devil is traditionally associated with bondage, attachment, and material temptation. The chains connecting the figures are a strong image for examining limits and complicity. This is a prompt to investigate a situation, not to blame someone for constraints, deny structural difficulties, or label a person as evil.",symbolism:[{element:"The chains",description:"Attachments and restrictions whose nature deserves a closer look."},{element:"The torch",description:"Desire and energy that can illuminate or consume attention."},{element:"The two figures",description:"Patterns that can be shared, learned, or reinforced in relationship."}],reflectionPrompts:["What is this attachment giving you, and what is it costing you?","Where is one realistic choice available, even if the whole situation cannot change yet?"]},"the-tower":{imagePath:"/cards/the-tower.svg",keywords:["Disruption","Reassessment","Rebuilding"],uprightMeaning:"When an assumption stops holding, the first useful response may be to find your footing. The Tower invites you to ask what has become difficult to ignore and which foundations deserve a closer look. You do not have to welcome disruption to learn from it. Start with what provides safety and support, then decide what is worth rebuilding.",traditionalInterpretation:"The Tower traditionally depicts lightning striking a crowned structure. It is associated with upheaval and the exposure of unstable arrangements. Here, that image is used to examine assumptions and resilience; drawing the card does not announce a coming crisis or make disruption necessary for growth.",symbolism:[{element:"The lightning",description:"A sudden recognition that changes the way a structure is understood."},{element:"The falling crown",description:"Authority or certainty that no longer seems secure."},{element:"The stone structure",description:"The foundations we build around beliefs, plans, or identities."}],reflectionPrompts:["Which assumption deserves attention before you build more on top of it?","What would help you feel supported while you reassess?"]},"the-star":{imagePath:"/cards/the-star.svg",keywords:["Hope","Renewal","Trust"],uprightMeaning:"Hope does not have to be a prediction that everything will work out. It can be the quieter choice to care for what is still growing. The Star invites you to notice the people, practices, and possibilities that help restore your sense of connection.",traditionalInterpretation:"Following the Tower in the Major Arcana, the Star is traditionally associated with renewal after disruption. Water poured onto land and into a pool connects inner nourishment with participation in the world. Its hope is restorative, rather than a guarantee of a particular outcome.",symbolism:[{element:"The eight-pointed star",description:"A point of orientation when certainty is unavailable."},{element:"The flowing water",description:"Care given freely, and the gradual return of energy."},{element:"The open landscape",description:"Space to be honest and begin restoring a relationship with yourself."}],reflectionPrompts:["What helps you feel quietly hopeful without needing a guarantee?","Where could a small act of care make room for renewal?"]},"the-moon":{imagePath:"/cards/the-moon.svg",keywords:["Uncertainty","Imagination","Discernment"],uprightMeaning:"An incomplete picture can invite both imagination and anxiety. The Moon asks you to notice the story you are filling into the gaps. Feelings may be telling you something important about your experience without establishing what is happening outside it. Move gently, gather another piece of information, and allow a question to remain open when certainty is not yet available.",traditionalInterpretation:"The Moon is associated with dreams, uncertainty, and what is only partially visible. A path passes between towers while creatures respond to the moonlight. The image supports reflection on ambiguity and instinct; it does not establish that someone is deceiving you or that a fear is a fact.",symbolism:[{element:"The moonlight",description:"Enough visibility to notice something, but not necessarily to understand it fully."},{element:"The winding path",description:"Moving through uncertainty without seeing the entire route."},{element:"The responding animals",description:"Different instinctive reactions to the same unknown."}],reflectionPrompts:["What do you know, what do you feel, and what are you currently imagining?","What information would help without requiring immediate certainty?"]},"the-sun":{imagePath:"/cards/the-sun.svg",keywords:["Joy","Clarity","Vitality"],uprightMeaning:"Pleasure and clarity can be useful information, too. The Sun invites you to notice where you feel more alive, more at ease, or less divided against yourself. Let an ordinary good thing register without immediately turning it into a task. A moment of warmth does not settle every difficulty; it can still show you something worth making room for.",traditionalInterpretation:"The Sun is commonly associated with openness, vitality, and joy. Its bright sun, child, and sunflowers emphasize life becoming visible and expressive. The card can encourage appreciation and confidence without promising uninterrupted happiness, success, or the absence of difficulty.",symbolism:[{element:"The sun",description:"Illumination and energy that make things easier to see."},{element:"The child",description:"Expression that is less governed by the need to appear accomplished."},{element:"The sunflowers",description:"Attention turning toward what nourishes life."}],reflectionPrompts:["What brings you an uncomplicated sense of being alive?","Which good thing could you allow yourself to enjoy without earning it first?"]},judgement:{imagePath:"/cards/judgement.svg",keywords:["Recognition","Renewal","Self-assessment"],uprightMeaning:"You are allowed to reconsider who you have been without reducing yourself to a verdict. Judgement invites a wider view of your choices, the expectations you inherited, and the direction you want to answer now. Notice what you have learned and what no longer feels honest. A meaningful next step can come from recognition rather than a demand to become a perfect new person.",traditionalInterpretation:"Traditionally, a trumpet calls figures to rise, linking Judgement with awakening and renewal. The image can be read as an invitation to respond to a deeper calling or reassess a life. In this experience, it opens a question about self-understanding and direction, rather than delivering a moral judgment about your worth.",symbolism:[{element:"The trumpet",description:"Something that asks for your attention or a considered response."},{element:"The rising figures",description:"The possibility of understanding yourself beyond an old definition."},{element:"The open sky",description:"A wider context in which to reconsider a personal story."}],reflectionPrompts:["Whose judgment are you carrying, and what do you actually believe about your direction?","What have you learned that could change the way you respond now?"]},"the-world":{imagePath:"/cards/the-world.svg",keywords:["Completion","Integration","Participation"],uprightMeaning:"There may be something to acknowledge before you rush toward the next beginning. The World invites you to notice what has come together, what you have learned, and how a chapter has changed your relationship with the wider world. Completion does not require perfection. You can mark an ending, carry its lessons, and leave room for what is still unfinished.",traditionalInterpretation:"The World traditionally marks the conclusion of the Major Arcana sequence. A central figure appears within a wreath, with four witnesses around it. The image is associated with fulfillment and integration, while its circular form can also suggest that an ending becomes part of another beginning.",symbolism:[{element:"The wreath",description:"A boundary that marks a completed cycle without sealing off the future."},{element:"The central figure",description:"A person finding a way to participate with more of themselves present."},{element:"The four witnesses",description:"Different dimensions of experience belonging to a larger whole."}],reflectionPrompts:["What deserves to be acknowledged as complete, even if it was not perfect?","Which lesson from this chapter would you like to carry into the next?"]}},g=[{id:"majorArcana",cards:a.Y.majorArcana.map(e=>({...e,...m[e.id]}))},{id:"cups",cards:r},{id:"wands",cards:h},{id:"swords",cards:d},{id:"pentacles",cards:u}],p=g.flatMap(({cards:e})=>e),f=new Map(p.map(e=>[e.id,e])),w={id:"within",name:"The Within Deck",system:a.Y,cards:p,cardIds:p.map(e=>e.id),catalog:p,groups:g};function y(e){return f.get(e)}e.s(["Z",0,y,"O",0,w],7364);let b=e=>"https://commons.wikimedia.org/wiki/File:"+encodeURIComponent(e.replaceAll(" ","_"));function v(e,t){let a=`/cards/${e}`;return{imagePath:`${a}/${t}.webp`,detailImagePath:`${a}/${"wirth"===e?"detail":"original"}/${t}.jpg`}}let T=[["What might the figure be about to leave behind?","你觉得人物正要把什么留在身后？"],["What do you notice about the direction of the figure’s attention?","人物的注意力似乎朝向哪里？"],["How would the scene change if the figure moved one step?","如果人物往前一步，画面会怎样变化？"],["What would you ask this figure before giving them advice?","如果要给画中人物建议，你想先问什么？"],["Which part of the image feels most deliberate to you?","画面中哪一处最像是有意为之？"],["Where do you sense ease or effort in the figure’s posture?","从人物的姿态里，你在哪儿感到轻松或费力？"],["What seems to give this figure room to act?","画面里有什么让这个人物有行动的余地？"],["Where does your gaze pause, and what might that pause tell you?","你的目光在哪儿停住？那个停顿让你想到什么？"],["What changes if you imagine this scene from the figure’s point of view?","如果从人物的视角看，这一幕会有什么不同？"],["Which detail would you notice first if the colors were gone?","如果去掉色彩，你会先看到哪个细节？"],["What can you see here before assigning the scene a meaning?","在给画面下定义前，你看见了什么？"],["What might make the next moment in this scene feel different?","什么可能让这幕场景的下一刻有所不同？"],["Which part of the image feels familiar, and why?","画面里哪一处让你感到熟悉？为什么？"],["What does the figure’s pose make you curious about?","人物的姿态让你好奇什么？"],["What would you like to know about the setting beyond the frame?","画框之外的场景，有什么是你想知道的？"],["Which detail softens or complicates your first impression?","哪个细节改变了你最初的印象？"],["Where is the tension in the scene, and where is the space around it?","画面中的紧张感来自哪里，哪里还有空间？"],["If this picture were a pause, what might come after it?","如果这幅画是一次停顿，之后可能发生什么？"],["How does the figure occupy the space around them?","人物是怎样占据周围空间的？"],["What stands out when you look at the background first?","先看背景时，什么显得特别突出？"],["Which part of the scene would you describe first to someone else?","如果把场景讲给别人，你会先说哪一部分？"],["What does this figure make you want to look at more carefully?","这个人物让你想更仔细地看什么？"]],k={cups:["Cups","圣杯"],wands:["Batons","权杖"],swords:["Swords","宝剑"],pentacles:["Coins","钱币"]},W=[["What would you notice if you began with a single detail?","如果只从一个细节看起，你会注意到什么？"],["What feels balanced or uneven between the two forms?","两种形状之间，哪里平衡，哪里不对称？"],["Which of the three forms changes how you see the other two?","三种形状中，哪一个改变了你看另外两个的方式？"],["How does the picture make room for each of its four forms?","画面怎样为四个形状各自留下空间？"],["Where does the repetition break, and what catches your attention there?","重复在哪里被打断？那里有什么吸引你？"],["Which parts of the arrangement seem to answer one another?","构图中哪几处像是在彼此呼应？"],["What do you notice at the edge before looking at the center?","先看边缘再看中央时，你注意到了什么？"],["Which pattern becomes clearer when you look again?","再看一遍时，哪个图案变得更清楚了？"],["Where can your eye rest amid the repetition?","在重复的图案之间，你的目光能在哪里停一下？"],["What feels complete in this arrangement, and what still feels open?","这个构图中，什么已经完整，什么还留有余地？"],["Which detail makes this figure seem ready to learn something?","哪个细节让你觉得人物准备好学点什么？"],["What gives the mounted figure a sense of direction?","画面中什么赋予骑马的人物方向感？"],["What do the figure’s pose and surroundings suggest to you?","人物的姿态和周围的事物让你想到什么？"],["How does this figure hold or share the space around them?","这个人物怎样掌握或分享周围的空间？"]];function A(e){return("sola-busca"===e?["cups","pentacles","wands","swords"]:["cups","wands","swords","pentacles"]).map(n=>({id:n,cards:a.Y[n].map((a,o)=>{let[i,r]=k[n],s="dodal"===e?t.D[n]+(0,t.w)(o+1):(0,t.w)(t.k[n]+o),h="page"===a.rank?"Knave":a.name.split(" of ")[0],l=`${h} of ${i}`,d=a.nameZh.replace(/^(圣杯|权杖|宝剑|星币)/,r),c="dodal"===e&&o<10?[`Notice how the ${i.toLowerCase()} and the spaces between them form a pattern in the woodcut.`,`留意木刻里${r}的排列，以及图案之间留出的空隙。`]:[`Look for how the ${i.toLowerCase()} share the engraved scene with its other details.`,`留意${r}如何与画面里的其他细节一起构成这一幕。`];return{id:`${e}-${s.toLowerCase()}`,edition:e,group:n,numeral:o<10?a.numeral:"",name:l,nameZh:d,...v(e,s),reference:b("dodal"===e?`Jean Dodal ${s}.jpg`:`Sola Busca tarot card ${s}.jpg`),observation:c,prompt:W[o]}})}))}let I=[["The Fool","愚者","Le Fol","","A traveler moves with a bundle while an animal tugs from behind.","行旅者背着包袱前行，身后的动物扯住他的衣服。","What is asking you to move on, and what is tugging you back?","什么在催你往前走，什么又把你往回拉？"],["The Juggler","魔术师","Le Bateleur","I","The juggler stands at a table of small tools and objects.","表演者站在摆着各式小器具的桌前。","Which tool already at hand could help you start?","手边哪一样工具能帮你迈出第一步？"],["The Popess","女教皇","La Papesse","II","The seated figure holds an open book.","坐着的人物手里捧着一本打开的书。","What would repay a slower reading?","有什么值得你放慢速度，重新读一遍？"],["The Empress","皇后","L’Impératrice","III","A crowned figure holds a scepter and an eagle shield.","头戴王冠的人物手持权杖和鹰纹盾牌。","What would you like to give shape to?","你想让什么逐渐成形？"],["The Emperor","皇帝","L’Empereur","IIII","The emperor sits in profile, one leg crossed, beside an eagle shield.","皇帝侧身而坐，交叠双腿，身旁有鹰纹盾牌。","Which boundary could make room for something you value?","哪一条界限能给你珍视的东西留出空间？"],["The Pope","教皇","Le Pape","V","The central figure raises a hand above two people below.","中央的人物举起手，下方站着两个人。","Which piece of advice would you like to examine for yourself?","哪一条建议值得你亲自检验？"],["The Lover","恋人","L’Amoureux","VI","Three figures meet under an archer in the sky.","三个人聚在一起，上方有一位执弓者。","What changes when you name the choice in your own words?","用自己的话说出这个选择之后，你的感受有什么变化？"],["The Chariot","战车","Le Chariot","VII","Two horses stand below a figure under a canopy.","华盖下站着一位人物，前方有两匹马。","What would help two competing impulses move in the same direction?","怎样才能让两股相反的冲动朝同一个方向走？"],["Justice","正义","La Justice","VIII","The figure holds both a sword and a set of scales.","人物一手持剑，一手持天平。","What belongs on each side of the scales?","如果把这件事放上天平，两端各该放什么？"],["The Hermit","隐者","L’Hermite","VIIII","A cloaked traveler lifts a lantern and carries a staff.","披着斗篷的旅人提灯拄杖。","What can you see clearly within the next few steps?","眼前几步之内，有什么是你已经看清的？"],["Wheel of Fortune","命运之轮","La Roue de Fortune","X","Figures ride different parts of a turning wheel.","几个形象处在轮子的不同位置。","What can you keep steady while circumstances turn?","外在情形变化时，有什么是你能稳住的？"],["Strength","力量","La Force","XI","A woman places her hands around the jaws of a lion.","女子把双手放在狮子的嘴边。","What might respond to a gentler kind of strength?","什么也许更适合用温和一点的力量来面对？"],["The Hanged Man","倒吊人","Le Pendu","XII","A figure hangs by one foot between two supports.","人物一只脚被吊在两根支柱之间。","What looks different if you wait before acting?","如果先等等再行动，什么会看起来不一样？"],["The Unnamed Card","无名牌","","XIII","A skeleton sweeps a scythe across the ground. The card carries no title.","骷髅挥动镰刀扫过地面，牌面没有标题。","What can you stop tending to make room for something else?","你可以不再维持什么，好给别的事腾出空间？"],["Temperance","节制","Tempérance","XIIII","A winged figure pours between two vessels.","有翼的人物在两个容器之间倒水。","What could you adjust a little rather than all at once?","有什么可以一点点调节？"],["The Devil","恶魔","Le Diable","XV","Two smaller figures stand tethered below a winged figure.","有翼人物下方的两个小人物被绳索系住。","Which tie feels stronger than you would like?","哪一种牵绊比你希望的更紧？"],["The House of God","神之屋","La Maison Dieu","XVI","The top of a tower opens and two figures fall beside it.","塔顶敞开，两个人物在塔旁落下。","What would still matter if the structure around it changed?","如果周围的结构变了，什么依然重要？"],["The Star","星星","L’Étoile","XVII","A kneeling figure pours from two vessels beneath a field of stars.","星群之下，跪着的人物从两个容器里倒水。","What small thing would you gladly keep caring for?","你愿意继续照料哪一件小事？"],["The Moon","月亮","La Lune","XVIII","Two animals face the moon while a creature rises from the water.","两只动物面向月亮，一只生物从水中浮现。","What can you observe before deciding what it means?","在下结论之前，你能先观察到什么？"],["The Sun","太阳","Le Soleil","XVIIII","Two figures stand together under the sun.","太阳下，两个人物站在一起。","Who makes it easier for you to be seen as you are?","和谁在一起时，你更容易自在地被看见？"],["Judgement","审判","Le Jugement","XX","A trumpet sounds above three figures.","三个人物上方，号角响起。","What is worth answering after a long silence?","沉默了一段时间后，什么值得你作出回应？"],["The World","世界","Le Monde","XXI","A figure stands within an oval wreath framed by four beings.","人物站在椭圆花环中，四周围着四个形象。","What pieces are beginning to fit together?","哪些原本分散的部分开始拼在一起了？"]].map(([e,a,n,o,i,r,s,h],l)=>({id:`dodal-m${(0,t.w)(l)}`,edition:"dodal",group:"majorArcana",name:e,nameZh:a,originalTitle:n,numeral:o,...v("dodal","M"+(0,t.w)(l)),reference:b(`Jean Dodal M${(0,t.w)(l)}.jpg`),observation:[i,r],prompt:[s,h]})),P=[["0","Mato","马托"],["I","Panfilio","潘菲利奥"],["II","Postumio","波斯图米奥"],["III","Lenpio","伦皮奥"],["IIII","Mario","马里奥"],["V","Catulo","卡图洛"],["VI","Sesto","塞斯托"],["VII","Deo Tauro","德奥·陶罗"],["VIII","Nerone","尼禄"],["VIIII","Falco","法尔科"],["X","Venturio","文图里奥"],["XI","Tulio","图利奥"],["XII","Carbone","卡尔博内"],["XIII","Catone","卡托"],["XIIII","Bocho","博科"],["XV","Metelo","梅特洛"],["XVI","Olivo","奥利沃"],["XVII","Ipeo","伊佩奥"],["XVIII","Lentulo","伦图洛"],["XVIIII","Sabino","萨比诺"],["XX","Nenbroto","嫩布罗托"],["XXI","Nabuchodenasor","尼布甲尼撒"]].map(([e,a,n],o)=>({id:`sola-busca-${(0,t.w)(o)}`,edition:"sola-busca",group:"majorArcana",name:a,nameZh:n,numeral:e,...v("sola-busca",(0,t.w)(o)),reference:b(`Sola Busca tarot card ${(0,t.w)(o)}.jpg`),observation:[`This Sola Busca trump bears the name ${a}. Look at how the figure is posed and what the artist places around them.`,`这张索拉\xb7布斯卡王牌题名 ${a}。可以先看人物的姿态，再看画家在周围放了什么。`],prompt:T[o]})),x=[["Le Fou","The traveler strides past a small animal, with a bundle balanced across their shoulders.","旅人肩上横挑着包袱，大步经过脚边的小动物。"],["Le Bateleur","One hand lifts a wand while the other rests near the objects on the table.","一只手举起短杖，另一只手靠近桌上的器具。"],["La Papesse","A red-robed figure holds an open book between two columns and a pale curtain.","红袍人物捧着打开的书，身后是两根柱子和一幅浅色帘幕。"],["L’Impératrice","The crowned figure sits between pale blue wings with a shield and scepter.","戴冠的人物坐在浅蓝色双翼之间，手持盾牌和权杖。"],["L’Empereur","The emperor sits sideways on a stone seat, holding a scepter upright.","皇帝侧坐在石座上，竖握权杖。"],["Le Pape","A raised hand and a triple cross sit above two figures seen from behind.","举起的手和三重十字架下方，是两个背对我们的身影。"],["L’Amoureux","A winged archer hovers in a burst of color above three figures.","三个人物上方，有翼的弓箭手悬在一簇彩色光芒中。"],["Le Chariot","Two sphinxes sit beneath the chariot, one pale and one dark.","战车下方坐着两只斯芬克斯，一明一暗。"],["La Justice","An upright sword and a pair of scales frame the seated figure.","坐着的人物两侧，一边是竖直的剑，一边是天平。"],["L’Ermite","A yellow lantern peeks out from the fold of the hermit’s blue cloak.","一盏黄色提灯从隐者的蓝色斗篷边露出来。"],["La Roue de Fortune","A winged figure sits above the wheel as two creatures cling to its sides.","有翼的形象坐在轮顶，两只生物攀在轮子两侧。"],["La Force","The figure looks down at the lion, hands resting at its jaws.","人物低头看向狮子，双手搭在它的嘴边。"],["Le Pendu","The hanging figure crosses one leg behind the other between two trees.","倒悬的人物在两棵树之间，把一条腿交叉在另一条腿后。"],["La Mort","The skeleton bends over the ground with a scythe in its hands.","骷髅手握镰刀，俯身朝向地面。","Death","死神"],["La Tempérance","A winged figure tips one vessel toward another in a steady stream.","有翼的人物倾斜手中的容器，让水流进另一只容器。"],["Le Diable","Two small figures stand tethered beneath a winged figure on a pedestal.","底座上的有翼人物下方，站着两个被系住的小身影。"],["Le Feu du Ciel","A strike from above breaks open the tower as two figures tumble below.","天火击开塔顶，两个人物向下坠落。","The Fire from Heaven","天火"],["Les Étoiles","A kneeling figure pours from two vessels beneath a large central star.","一颗大星下，跪着的人物倾倒手中的两只容器。","The Stars","星星"],["La Lune","Below the moon, two animals face each other across a path from the water.","月亮下，两只动物隔着一条从水边延伸的小路相对。"],["Le Soleil","Two figures meet beneath a bright sun and its colored rays.","两个身影在明亮的太阳和彩色光芒下相遇。"],["Le Jugement","A trumpet sounds above a figure rising with their back to us.","号角响起，下方有个背对我们的人物正在起身。"],["Le Monde","A figure stands inside an oval wreath, framed by four beings.","人物立于椭圆花环之中，四周围着四个形象。"]].map(([e,a,n,o,i],r)=>{let s=(0,t.w)(r),h=e.normalize("NFD").replace(/\p{Diacritic}/gu,"").replaceAll("’","'"),l=I[r];return{id:`wirth-${s}`,edition:"wirth",group:"majorArcana",name:o??l.name,nameZh:i??l.nameZh,originalTitle:e,numeral:0===r?"":String(r),...v("wirth",s),reference:b(`${s} ${h}, Oswald Wirth Tarot Deck 1889 BnF.jpg`),observation:[a,n],prompt:l.prompt}}),j={dodal:[{id:"majorArcana",cards:I},...A("dodal")],"sola-busca":[{id:"majorArcana",cards:P},...A("sola-busca")],wirth:[{id:"majorArcana",cards:x}]},C=Object.values(j).flatMap(e=>e.flatMap(e=>e.cards)),M=new Map(C.map(e=>[e.id,e]));function L(e){return"edition"in e}[...w.catalog,...C];let S={dodal:["dodal-m09","dodal-m17"],"sola-busca":["sola-busca-13","sola-busca-17"],wirth:["wirth-09","wirth-17"]};e.s(["i",0,function(e,t,a="thumbnail"){return L(e)?"detail"===a?e.detailImagePath:e.imagePath:"within"===t?e.imagePath:"soimoi"===t?`/cards/soimoi/${e.id.replace(/^the-/,"")}.webp`:"van-gogh"===t&&"major"===e.arcana?`/cards/van-gogh/${"detail"===a?"detail/":""}${e.id}.webp`:`/cards/classic/${e.id}.webp`},"S",0,function(e,t){return`/deck/${e.id}/${L(e)?"":`?artwork=${t}`}`},"o",0,function(e){return(0,t.b)(e)?S[e]:["the-hermit","the-star"]},"N",0,function(e,t="majorArcana"){return`/?deck=${"majorArcana"===t?"open":t}&artwork=${e}#deck`},"T",0,function(e){return"van-gogh"===e?w.groups.slice(0,1):(0,t.b)(e)?j[e]:w.groups},"n",0,function(e){let t=M.get(e)??y(e);if(!t)throw Error(`Unknown card: ${e}`);return t},"p",0,L],31263);let H={"the-fool":{uprightMeaning:"还没想清所有答案就开始，也是一种智慧。愚者邀请你留意，好奇心正悄悄把你引向哪里。面对陌生的事，你可以慎重地迈出一小步，把后面的路留给沿途的发现。",traditionalInterpretation:"愚者常位于大阿尔卡那的开端，像一位走入未知的旅人。传统牌义与率性、天真和风险有关。新的可能性让人欣喜，也提醒你看清脚下。",symbols:[["开阔的地平线","未来还有许多未定的可能。"],["小小的旅人","带着手头已有的东西出发，把一些旧期待留在身后。"],["悬崖","自由与责任相遇的地方。纵身一跃也是一个选择。"]],reflectionPrompts:["如果一开始可以做得不熟练，你会想探索什么？","今天，你可以迈出哪一小步？"]},"the-magician":{uprightMeaning:"你的专注力、经验和身边的工具，或许已经足够让你开始。魔术师邀请你把一个意愿变成具体行动。发现自己手边已经有什么，往往就是找到办法的第一步。",traditionalInterpretation:"魔术师把意愿和现实行动联系起来。传统画面中，桌上放着四个牌组的象征，表示可以调动的资源。这张牌关联技巧和主动性，也提醒人诚实看待自己实际做了什么。",symbols:[["举起的手","一个想法正等待通过有意识的行动表达出来。"],["桌子","把资源聚在一起，让意愿进入实践。"],["无限符号","学习、创造、重新开始，彼此循环。"]],reflectionPrompts:["哪样资源因为太熟悉，反而被你忽略了？","做什么能让你的意愿具体可见？"]},"the-high-priestess":{uprightMeaning:"有些想法在你不急着说出它们时，反而更清楚。女祭司给观察、不确定和尚未说出口的认识留出空间。听听自己的感受，再让经历帮你检验它。",traditionalInterpretation:"女祭司坐在两根柱子之间，传统上守护着通往知识的门槛。月亮、隐藏的文字与帘幕暗示，理解往往一点点显现。直觉可以是继续探究的起点。",symbols:[["两根柱子","让不同视角并存，暂时不必选边。"],["新月","能感到、能看清的东西会随时间变化。"],["帘幕","眼下可见的，只是事情的一部分。"]],reflectionPrompts:["你已经察觉到什么，却还没给它一个名字？","如果在决定前停一停，什么可能变得更清楚？"]},"the-empress":{uprightMeaning:"有些珍贵的事，需要的是照料。皇后邀请你留意让生活与创造力生长的条件，比如休息、关注、滋养，以及试一试的空间。想想哪件事值得你持续照顾，你又能否收下自己常给别人的那份善意。",traditionalInterpretation:"皇后常与自然、生育和丰饶的创造力相连。星冠、谷物和舒适的座椅，把她放在万物生长的景象里。这里的孕育也指培养想法、关系与日常生活的能力。",symbols:[["生长的谷物","耐心照料与适宜条件共同带来的结果。"],["星冠","关怀把个人与更广阔的世界相连。"],["休憩的座椅","既能给出安慰，也能接受安慰。"]],reflectionPrompts:["生活中哪件事得到照料后，会长得更好？","在哪件事上，你可以让自己接受一些支持？"]},"the-emperor":{uprightMeaning:"清楚的边界或可靠的习惯，能给生活留出喘息的空间。皇帝邀请你看看，哪些结构在支撑你珍视的事，哪些已变成僵化的惯例。试着承担一项责任、说明一个界限，或建立一套能让行动更稳的小办法。",traditionalInterpretation:"皇帝传统上坐在石座上，象征权威、秩序和共同体的现实基础。它既涉及领导与责任，也引出一个问题：当一套规则变得难以改变时，它究竟在照顾谁的需要？",symbols:[["石座","稳固的基础，也可能因此难以改动。"],["群山","既有结构的持久与局限。"],["权杖","为自己如何使用影响力负责。"]],reflectionPrompts:["哪条边界能让你的自由更持久？","哪些是你的责任，哪些结果是你想控制的？"]},"the-hierophant":{uprightMeaning:"许多事情可以和别人一起学明白。教皇邀请你看看，哪些教导、群体与传下来的规则塑造了你的选择。有些能给你支持，有些值得再问一句。找一位欢迎你好奇的老师，或一种允许你保留判断的共同实践。",traditionalInterpretation:"教皇与宗教教导、制度和共有知识的传承有关。坐着的老师和交叉的钥匙暗示，眼前有一扇通往既有传统的门。向别人学习的同时，也可以审视这套传统的前提。",symbols:[["老师","知识在人与人之间传递。"],["交叉的钥匙","通往同一套知识，可以有不同的入口。"],["两位学生","学习、群体与共同期待带来的影响。"]],reflectionPrompts:["你继承的观念里，哪些仍帮得到你？哪些值得重看？","谁能帮你想得更清楚，也欢迎你继续发问？"]},"the-lovers":{uprightMeaning:"一段有意义的关系，常会邀请你更诚实地出现。恋人牌可以照见关系，也可以帮助你审视选择与价值观是否一致。留意你同意了什么、什么还没说出口，以及一个决定能否同时容纳亲近与各自的独立。",traditionalInterpretation:"恋人牌与关系、吸引和有分量的选择相连。在韦特体系的画面中，两个人站在天使下方，身后是两棵不同的树。它可以用来思考价值的一致和彼此的看见。",symbols:[["两个人","与另一个人相遇，同时为自己的选择负责。"],["上方的天使","眼前的愿望之外，还有哪些值得考虑的价值？"],["两棵树","不同的经历与观点进入同一段关系。"]],reflectionPrompts:["什么选择能让你的行动更靠近你珍视的事？","多说一点真话，会让哪段关系更有来有往？"]},"the-chariot":{uprightMeaning:"当互相拉扯的优先事项有了共同方向，行动就会容易一些。战车邀请你认真选择一个承诺。问问自己，精力流向了哪里，什么在把它拉开，又有哪些支持能让你稳稳走向自己选定的目标。",traditionalInterpretation:"战车传统上指向决心、意志和行动。两只不同的生物提示，有些力量需要协调。它的向前姿态也值得追问：你正在驶向有意义的地方，还是仅仅顺着惯性在走？",symbols:[["不同的斯芬克斯","不同的驱动力可以协作，各自仍有不同。"],["星空华盖","把选定的方向放在更广阔的背景里。"],["车轮","靠一次次寻常行动，让承诺动起来。"]],reflectionPrompts:["哪个目标真正值得你投入精力？","哪些互相拉扯的需求可以协调在一起？"]},strength:{uprightMeaning:"力量有时是与不舒服的感受多待一会儿，是把话说清楚的勇气，也是让冲突降温的克制。这张牌邀请你用温和与边界来面对本能。强烈的感受可以被承认，行动仍可以由你选择。",traditionalInterpretation:"这套体系里的力量牌描绘了一个人平静地照看狮子。画面把勇气、温柔与持续的关注放在一起，可以看成觉察与本能之间的一次对话。",symbols:[["狮子","活力、欲望、愤怒，以及其他强烈的本能。"],["温柔的双手","关注本身就能带来影响。"],["无限符号","一次次稳稳地面对自己。"]],reflectionPrompts:["不必变得强硬时，勇气会是什么样子？","哪种感受可以先承认，暂时不必采取行动？"]},"the-hermit":{uprightMeaning:"拉开一点距离，或许能重新听清自己的想法。隐者提供一个主动的停顿，让你暂时远离别人的催促和期待。独处可以帮助你理清在乎的事，再带着更稳的方向感回到生活中。",traditionalInterpretation:"隐者提着灯走在山间。传统牌义与学习、反思和寻找智慧有关，也提示辨别需要耐心。独处能带来帮助，同时可以留意自己何时开始回避。",symbols:[["提灯","整条路尚未看清，眼前这一小步已经有了光。"],["山","在时间、经历与努力中慢慢获得的视野。"],["手杖","让独自探索得以持续的习惯与支持。"]],reflectionPrompts:["没有旁人看着时，你仍然在乎什么？","你需要的独处，和你想念的连接，分别是什么？"]},"wheel-of-fortune":{uprightMeaning:"变化未必能说明你做得好不好。命运之轮邀请你分清，哪些事可以影响，哪些正在你周围自行变化。看一看其中的规律，也给它改变的余地。你可以做一点调整、准备一个备选方案，或者留意意外出现的机会。",traditionalInterpretation:"转动的轮子传统上象征境遇变化与运势起伏。围绕它的人物，处在同一次转动的不同位置。这里借这个画面来思考不确定性，以及人在变化中如何调整。",symbols:[["转轮","即使我们希望一切如旧，条件也会变化。"],["起落的人物","眼下的位置也许只是暂时的。"],["周围的见证者","作出回应之前，可以先观察变化的规律。"]],reflectionPrompts:["面对正在发生的变化，你能怎样回应，同时放下对自己的评判？","哪一项小调整是你做得到的？"]},justice:{uprightMeaning:"想把事情看清楚，可以先分开三件事：发生了什么、你原本想做什么、它造成了什么影响。正义邀请你考虑证据、后果，以及受决定影响的人怎么看。承担责任能为修复打开空间，也可以问问自己，你是否在用过于苛刻的尺度衡量自己。",traditionalInterpretation:"正义牌通常画有天平和直立的剑，把慎重衡量与明确判断放在一起。它引出关于责任和公平的问题，也为理解不公平的处境留出空间。",symbols:[["天平","在得出结论前，衡量证据与不同角度。"],["直立的剑","作出区分需要清晰，也需要承担责任。"],["端正的座椅","停一下，看看自己的判断以什么为依据。"]],reflectionPrompts:["哪项证据或哪个角度，能让你的判断更公平？","如果不把承担责任变成自我惩罚，你会怎么做？"]},"the-hanged-man":{uprightMeaning:"如果不断努力还是得到同一个答案，换个角度也许比再推一把更有用。倒吊人建议你主动停一下，放下一个熟悉的假设，再看看有什么变化。你可以离开最初的立场，重新理解问题。",traditionalInterpretation:"传统画面里，被倒吊的人神情平静，头上有光环。这幅图常被读作主动放下、重排优先顺序，以及在静止中得到理解。停顿本身就可以有意义。",symbols:[["倒挂的人","从不熟悉的位置看熟悉的世界。"],["光环","停止一味用力时，可能出现领悟。"],["活着的树","看得见的进展暂时停止时，生活仍在继续。"]],reflectionPrompts:["放下哪个假设，你可能会看见另一种可能？","重视不同事情的人，会怎么看这件事？"]},death:{uprightMeaning:"一件事可以曾经很重要，如今也到了结束的时候。死神邀请你留意，哪种角色、期待或安排已经不再适合。放下时可能既难过又松一口气，两种感受都可以慢慢来。想想你想珍重什么、愿意放下什么，以及哪些支持能让过渡更从容。",traditionalInterpretation:"死神牌广泛被理解为结束与转变的象征。骑士、旗帜与远方的朝阳，把结束放在更大的循环之中。在这里，它是一道关于变化的反思提示。",symbols:[["骑士","变化越过了熟悉的角色或安排。"],["旗帜上的白花","放下的过程里，也许会出现新的生机。"],["升起的太阳","走出熟悉的范围后，生活仍然延续。"]],reflectionPrompts:["你可以让什么结束，同时珍重它曾经带给你的东西？","什么支持能让你按自己的节奏度过这次转变？"]},temperance:{uprightMeaning:"两种需求或许比看上去更能共存。节制邀请你耐心调整比例，比如放慢一点、少做一点，或找一种能同时容纳用力与恢复的节奏。平衡可以在实践里不断调整。",traditionalInterpretation:"节制牌中，有人在两个容器之间倾倒液体，常一脚踏地、一脚入水。传统牌义与适度和调和不同元素有关。这个画面也可以理解为主动整合：试一试，观察，再调整。",symbols:[["两个容器","不同资源、经历或需求之间的交换。"],["陆地与水","让实际的立足点和情绪体验同时存在。"],["远方的小路","通过耐心调整，一点点接近选定的方向。"]],reflectionPrompts:["哪两种需求可以换一种比例来安排？","哪个小尝试能帮你找到更可持续的节奏？"]},"the-devil":{uprightMeaning:"有些习惯或期待太熟悉，代价就很难察觉。恶魔邀请你好奇地看看，什么让你继续依附：是舒适、害怕、想被认可，还是一种需要支持才能改变的现实限制？看清模式，可能帮你找到原先没发现的一点选择。",traditionalInterpretation:"恶魔传统上与束缚、依附和物质诱惑相连。连接两个人物的锁链，让人想到限制如何产生，又如何被维系。阅读这张牌时，可以把注意力放在具体的处境上。",symbols:[["锁链","值得仔细辨认的牵绊与限制。"],["火炬","欲望与能量可以照亮眼前，也可能占去全部注意力。"],["两个人","有些模式会在关系里被分享、习得或强化。"]],reflectionPrompts:["这份依附带给你什么，又让你付出什么？","就算整个处境暂时难以改变，你还有哪一个现实的选择？"]},"the-tower":{uprightMeaning:"当一个假设不再成立，可以先让自己站稳。高塔邀请你看看，什么已经难以忽视，哪些基础值得重审。先找到能提供安全感和支持的事，再决定什么值得重建。",traditionalInterpretation:"高塔的传统画面是一道闪电击中带王冠的建筑。它与剧变，以及不稳定的安排被揭露有关。这里借它审视假设，也寻找变化之中可以依靠的东西。",symbols:[["闪电","突如其来的领悟，改变了你对既有结构的理解。"],["坠落的王冠","权威或确定感失去了原来的支撑。"],["石造的高塔","我们围绕信念、计划和身份搭建的基础。"]],reflectionPrompts:["继续在它上面建造之前，哪个假设值得你先看看？","重新审视这些事情时，什么能给你一些支持？"]},"the-star":{uprightMeaning:"希望也可以是一种安静的选择，去照料仍在生长的东西。星星邀请你留意，哪些人、习惯和可能性，让你重新感到和自己、和世界相连。",traditionalInterpretation:"星星在大阿尔卡那中接续高塔，传统上与动荡后的复苏有关。水同时被倒向土地与水池，把内在的滋养和参与外部世界联系起来。这里的希望，来自慢慢恢复的感受。",symbols:[["八角星","在没有把握时，仍能用来辨认方向的一点光。"],["流动的水","自由给出的关怀，以及慢慢回来的精力。"],["开阔的风景","留出诚实面对自己、修复自我关系的空间。"]],reflectionPrompts:["即使结果没有保证，什么仍能让你感到一点安静的希望？","在哪件事上，一点照料能给复苏留出空间？"]},"the-moon":{uprightMeaning:"看不全的事容易引出想象，也容易引出焦虑。月亮邀请你留意，自己正在用怎样的故事填补空白。感受能告诉你自己的经历，外在情况还需要更多信息。慢一点，找一条新的线索，也允许问题暂时悬着。",traditionalInterpretation:"月亮与梦、不确定性以及若隐若现的事物相连。小路从两座塔之间穿过，动物在月光下作出回应。这个画面可以用来理解暧昧的处境，以及本能是如何反应的。",symbols:[["月光","足够让你察觉些什么，还不足以看清全貌。"],["蜿蜒小路","看不到整条路，也可以穿过不确定性。"],["有反应的动物","面对同一个未知，不同本能会作出不同反应。"]],reflectionPrompts:["哪些是你知道的，哪些是你感受到的，哪些是你正在想象的？","在暂时没有确定答案时，哪条信息会有帮助？"]},"the-sun":{uprightMeaning:"愉快和清楚的感觉，也能提供线索。太阳邀请你留意，在哪里你感觉更有活力、更自在，也更能和自己相处。让一件平常的好事被你感受到，暂时不必把它变成任务。片刻温暖也能让你看见什么值得留在生活里。",traditionalInterpretation:"太阳常与开放、活力和喜悦相连。明亮的太阳、孩子和向日葵，让生命力变得可见，也有了表达的空间。这张牌可以提醒你去欣赏眼前的事，感受已有的信心。",symbols:[["太阳","光和能量，让眼前的事更容易看清。"],["孩子","把注意力放回真实表达，少一点证明自己的负担。"],["向日葵","把注意力转向滋养生活的事。"]],reflectionPrompts:["什么让你单纯地感到自己鲜活地活着？","有什么好事，你可以允许自己直接享受？"]},judgement:{uprightMeaning:"你可以重新理解过去的自己，给这段经历保留细节。审判邀请你把做过的选择、继承的期待，以及此刻愿意回应的方向放在一起看。留意你已经学会什么、什么已不再符合你的真实感受，再从这份认识里找一个下一步。",traditionalInterpretation:"传统画面中，号角唤起人们，把审判与觉醒、更新联系起来。它可以被读成回应内心呼唤，或重新理解一段人生的邀请。这里关注的是认识自己和选择方向。",symbols:[["号角","有件事正在请求你的注意，或需要一个慎重的回应。"],["起身的人们","可以在旧定义之外重新认识自己。"],["开阔的天空","在更广的背景里，重新审视自己的故事。"]],reflectionPrompts:["你背着谁的评价？对自己的方向，你真正相信什么？","你学到了什么，能改变自己现在的回应方式？"]},"the-world":{uprightMeaning:"急着开始下一段之前，或许有些东西值得先承认。世界邀请你看看，哪些事情终于汇合，你学到了什么，这一段又怎样改变了你与外界的关系。完成可以带着不完美。你可以为一段经历画上句号，带走所得，也给尚未完成的事留一点空间。",traditionalInterpretation:"世界通常位于大阿尔卡那的末尾。花环里有一个中心人物，周围有四位见证者。画面关联圆满与整合，圆环也让人想到，一个结束可以成为下一次开始的一部分。",symbols:[["花环","为一个已经走完的循环画出边界，未来仍然敞开。"],["中心的人物","带着更完整的自己参与生活。"],["四位见证者","经验的不同侧面，共同属于一个更大的整体。"]],reflectionPrompts:["即使还有不完美，哪件事也值得承认它已经完成？","你想把这一段学到的什么带进下一段？"]}};var q=e.i(59675);let $={"the-fool":[["The cliff edge","悬崖边缘","The traveler looks upward at the edge of a drop. Curiosity and attention can travel together.","旅人站在断崖边，抬头望天。好奇地往前，也可以留意脚下。"],["The white dog","白色小狗","The dog springs up close to the traveler’s heels, bringing attention back to the next step.","小狗在旅人脚边跃起，把目光拉回到眼前这一步。"],["The white rose","白玫瑰","A small flower held out to the open air suggests the pleasure of approaching something with curiosity.","旅人向空中举起一枝小花，像是带着好奇心迎向新鲜事物。"]],"the-magician":[["The wand and pointing hand","高举的短杖与下指的手","One gesture reaches up and the other points to the ground, linking an idea to something you can do.","一只手举杖向上，另一只手指向地面，把心里的想法和脚下能做的事连起来。"],["The four tools on the table","桌上的四件器物","The cup, sword, pentacle and wand invite you to take stock of what is already within reach.","杯、剑、星币和短杖都摆在手边，提醒你先看看自己已经有什么可用。"],["The blue infinity sign","蓝色无限符号","The loop over the figure’s head suggests that learning and practice keep feeding each other.","人物头顶的蓝色环线连绵往复，像是学习和练习彼此推动。"]],"the-high-priestess":[["The dark and light pillars","一深一浅的石柱","The two pillars hold the same space, leaving room for perspectives that differ.","深浅两根石柱撑起同一个空间，也给不同的看法留出位置。"],["The crescent at her feet","脚边的金色弯月","Only part of the moon is lit. What you notice may be one part of a larger picture.","月亮只亮了一部分。你此刻察觉到的，也许只是全貌的一角。"],["The pomegranate curtain","石榴纹帘幕","The patterned curtain gives the space behind her depth and keeps some of it out of sight.","带石榴图案的帘幕让身后的空间有了纵深，也遮住了其中一部分。"]],"the-empress":[["The golden grain","金色的谷穗","Grain bends across the foreground, making the results of patient care visible.","谷穗在画面前方弯下，耐心照料的结果变得可见。"],["The star crown","发间的星冠","Stars woven through the crown place the Empress within the same landscape she tends.","星星缀在冠上，让皇后看起来也是她所照料的天地的一部分。"],["The red cushions","红色软垫","The cushions support the Empress’s relaxed posture, giving rest a place alongside care.","红色软垫托住皇后放松的坐姿，让休息和照料一样有位置。"]],"the-emperor":[["The ram-headed throne","雕有公羊头的石座","The solid stone gives authority a foundation and shows how firmly it can set in place.","石座给权威一个稳固的根基，也让人看见结构一旦成形有多难挪动。"],["The mountain ridges","石座后的山脊","The ridges stretch beyond the throne, placing any one ruler within a larger set of limits.","山脊从石座后延伸开去。再有权力的人，也处在更大的环境和限制之中。"],["The scepter and orb","权杖与金球","Held in separate hands, these emblems invite reflection on the scope and use of influence.","权杖和金球分握在两手，让人想一想自己的影响能及于哪里，又会怎样使用它。"]],"the-hierophant":[["The raised hand","举起的手","The teacher addresses the people gathered below, making learning a relationship between people.","老师向面前的人举手示意，让学习成为人与人之间的交流。"],["The crossed keys","交叉的钥匙","Two keys lie at the foot of the seat, an image of access to a body of shared knowledge.","两把钥匙交叉放在座前，像是进入一套共同知识的入口。"],["The two learners","面向老师的两位学徒","Both turn toward the same teacher. Shared learning can offer support and shape expectations.","两位学徒面向同一位老师。共同学习能给予支持，也会塑造人们的期待。"]],"the-lovers":[["The two figures in the meadow","草地上相对的两人","They turn toward each other across an open space, with room for each person’s choice.","两人隔着一片空地相对，各自仍有做选择的余地。"],["The angel’s open arms","天使张开的双臂","The wide gesture gives the meeting a larger frame in which to consider what matters.","张开的双臂把这场相遇放进更大的画面，也提醒你想想什么真正重要。"],["The fruit tree and the tree of flame","果树与火焰般的树","One tree bears fruit and the other rises in orange curls, giving the two sides distinct backgrounds.","一边的树结着果实，另一边的树向上卷出橙色火焰，两个人各有不同的来处。"]],"the-chariot":[["The dark and pale sphinxes","一深一浅的斯芬克斯","Both are at rest in front of the chariot. Different impulses can be brought into alignment before you act.","两只斯芬克斯都伏在车前。行动之前，可以先把不同的冲动理顺。"],["The canopy of stars","星纹华盖","The stars over the charioteer invite you to consider the wider purpose guiding your next step.","车手头顶的星纹提醒你，下一步还可以由一个更长远的目标来引导。"],["The charioteer’s upright staff","车手竖握的权杖","The steady grip suggests choosing a direction even while the chariot is still.","车还停着，车手已经稳稳握住权杖。方向可以在出发之前选定。"]],strength:[["The lion’s mane","狮子翻卷的鬃毛","The lively orange strokes give instinct and energy a visible form.","橙色笔触在鬃毛里翻卷，让本能和力量有了看得见的形状。"],["The hands at the lion’s muzzle","轻扶狮子口鼻的双手","The figure leans in and holds the lion with care, suggesting the strength of sustained attention.","人物俯身轻扶狮子，显出持续留意和耐心照料也有力量。"],["The infinity sign","无限符号","The loop above the figure suggests that steadiness is a practice you return to.","头顶的环线连绵往复，像是一种可以反复练习的沉着。"]],"the-hermit":[["The light inside the lantern","提灯里的一点亮光","A small glow stands out against the blue night, enough to attend to what is close.","一点灯光从蓝色夜空里显出来，足够照见离自己最近的地方。"],["The snowy ledge","覆雪的山崖","The figure stands above the distant ridges, where distance can make a pattern easier to see.","人物立在远山上方，拉开一点距离之后，有些脉络反而更容易看清。"],["The walking staff","撑在雪地里的手杖","The staff gives the solitary figure a point of support on uncertain ground.","手杖撑在雪地里，给独自站在不稳地面上的人一个支点。"]],"wheel-of-fortune":[["The golden wheel","金色转轮","The wheel fills the center while clouds move around it, bringing change into view as a recurring pattern.","金色转轮占据画面中央，云在四周翻涌，把变化画成了反复出现的节奏。"],["The creatures around the wheel","转轮周围的生物","A sphinx sits above, with a serpent and a red creature on either side. Each occupies a different place in the same cycle.","斯芬克斯坐在上方，两侧是一条蛇和一只红色生物。它们在同一轮变化里各处一方。"],["The open books","四角摊开的书","The winged figures attend to their books while the wheel turns, making room for observation before action.","转轮在中央转动，四角的有翼身影守着摊开的书。变化中也有先观察的余地。"]],justice:[["The hanging scales","垂在手边的天平","The two pans give each side a place to be weighed before a judgment is made.","两个秤盘各有位置，让双方都能在下判断之前得到衡量。"],["The upright sword","竖起的剑","The straight blade makes a clear line through the folds of the curtain, evoking the clarity a decision can require.","直剑在弯曲的帘褶前划出清晰的一线，像是做决定时需要的分辨。"],["The seated figure between columns","两根石柱之间端坐的人","The centered posture leaves a moment to consider what a decision rests on.","人物在两根石柱之间坐得端正，让人有片刻去想一个判断究竟依据什么。"]],"the-hanged-man":[["The acrobat’s inverted pose","倒立的杂技演员","One leg reaches up and the other bends across it, giving the familiar garden a different point of view.","一条腿伸向上方，另一条腿屈起横过来。熟悉的花园也有了一个倒过来的视角。"],["The gold halo","头后的金色光晕","The glow surrounds a calm face, suggesting the clarity that sometimes arrives in a pause.","金色光晕环绕着平静的脸，像是停下来时才慢慢浮现的领悟。"],["The blue mat beneath","下方的蓝色软垫","The mat makes the pause feel supported. You can give yourself somewhere safe to try a different position.","软垫让这次停顿有了托底。试着换个姿势之前，也可以先给自己留好落脚的地方。"]],death:[["The rider on the white horse","白马上的骑士","The horse raises a foreleg as the rider moves on, giving change a direction through the scene.","白马抬起一条前腿，载着骑士前行，让变化在画面里有了方向。"],["The white flower on the black banner","黑旗上的白花","The pale flower remains visible against the dark cloth, suggesting what can still grow through an ending.","浅色的花在黑旗上依然醒目，让人想到一件事结束时仍可能有东西生长。"],["The light between the towers","双塔之间的晨光","The distant light opens another horizon beyond what is ending in the foreground.","前景里的事正在走向结束，双塔之间的远光却又打开一条新的地平线。"]],temperance:[["The stream between the cups","两只金杯之间的水流","A thin stream links the cups, showing that blending takes a series of careful adjustments.","细细的水流连着两只杯子。调和需要一次次小心地调整。"],["One foot in water, one on land","一脚入水，一脚踏岸","The figure keeps a footing on the bank while touching the water, making space for feeling and practical grounding together.","人物一脚站稳在岸上，另一脚探入水中。感受和实际的立足点，可以同时照顾到。"],["The path toward the light","通向亮处的小路","The path curves behind the figure. You can move toward a direction through several small turns.","小路在人物身后弯向亮处。朝一个方向走，也可以经过几次小小的转弯。"]],"the-devil":[["The slack chains","松垂的锁链","The chains hang in curves from the pedestal. Their slack invites a closer look at where there may be room to move.","锁链从石座上弯弯地垂下来。那一点松弛，让人想看看哪里或许还有活动的余地。"],["The small flames","几处小火焰","Flames light parts of the dark scene, drawing attention to what keeps drawing you back.","小火焰照亮暗处的几片地方，让人留意什么在反复牵动自己的注意力。"],["The two figures below the pedestal","石座下的两个人","Both reach toward the same center. A pattern can be reinforced when more than one person takes part in it.","两人都把手伸向同一个中心。当多个人参与其中，一种模式就可能被反复强化。"]],"the-tower":[["The curling lightning","卷曲的闪电","The bolt crosses the sky and hits the top of the tower, making a hidden weakness suddenly visible.","闪电卷过夜空击中塔顶，把原先看不见的薄弱处突然照了出来。"],["The crown knocked loose","被掀落的王冠","The crown is already in the air. What looked settled can lose its place very quickly.","王冠已经飞到了空中。看似稳固的东西，也可能一下子就离开原位。"],["The two falling figures","从两侧坠落的人","The figures are thrown in different directions, suggesting that the same disruption can affect people differently.","两个人向不同方向坠落。同一场变动，落到不同人身上也会有不同的影响。"]],"the-star":[["The swirling gold halo","旋涡状的金色星晕","Rippling rings of light give the moving sky a point to return to.","一圈圈金光在流动的夜空里扩开，给目光一个可以回到的地方。"],["The two clay pitchers","两只陶壶","One stream widens into ripples and the other runs along the grass. Care can take a different shape wherever it lands.","一股水落进池塘，荡开涟漪，另一股顺着草地流走。关怀到了不同的地方，也会变成不同的样子。"],["The bird on the branch","停在枝头的小鸟","A small figure stays still while the painted sky and landscape move around it.","天光和大地都在笔触里流动，枝头的一小点身影却安静地停着。"]],"the-moon":[["The moon’s pale profile","月亮的浅色侧脸","Its light reveals a few shapes at a time, leaving room for more than one reading of the scene.","月光只照出一部分形状，同一幅景象也就有了不止一种读法。"],["The path between the towers","双塔之间的弯路","The route remains visible even as it twists out of sight. You can follow the part you can see.","小路虽然一再转弯，眼前仍有一段看得见。可以先走那一段。"],["The crayfish in the pool","水里的螯虾","The crayfish rises from a ring of ripples, like a feeling coming into view before you can name it.","螯虾从一圈涟漪里冒出来，像一种还叫不出名字的感受渐渐浮现。"]],"the-sun":[["The sun’s curling rays","太阳弯卷的光芒","The light reaches over the whole scene, making even small things easier to notice.","阳光照过整个画面，连细小的事物也更容易被看见。"],["The rider with the red banner","举红旗的骑手","The lifted banner and the white horse’s stride give joy a visible movement.","举起的红旗和白马的步伐，让喜悦有了看得见的动作。"],["The sunflowers above the wall","墙头的向日葵","The flowers lift their faces into the light, an image of giving attention to what sustains you.","花朵从墙头探出，向着亮处抬起脸。也可以把注意力给那些让自己有生气的事。"]],judgement:[["The trumpet and banner","号角与旗帜","The angel raises the trumpet above the waves, giving a call a direction you can turn toward.","天使在波浪上方举起号角，像是让一句呼唤有了可以回望的方向。"],["The figures rising from stone boxes","从石棺中起身的人","They lift their arms as they rise, making awakening visible as an action.","人们起身时向上伸开手臂，把觉醒变成一个看得见的动作。"],["The water between them","石棺之间的水流","The current connects people in separate places, suggesting that a call can be heard in many ways.","水流穿过相隔的人们，像是同一种呼唤也会被不同的人听出不同的意思。"]],"the-world":[["The ribbon-tied wreath","系红带的花环","The wreath closes a circle around the dancer and gives their movement a place to continue.","花环在舞者周围合成一圈，也给舞步留出继续流动的空间。"],["The dancer’s two wands","舞者手中的两根短杖","Held out on either side, the wands extend the same gesture in two directions.","两根短杖一左一右伸开，让同一个动作朝两个方向延展。"],["The four corner figures","四角的身影","A winged person, eagle, bull and lion frame the dance. Very different presences can belong to one picture.","有翼的人、鹰、公牛和狮子围着舞者。很不相同的身影，也能各自在同一幅画里有位置。"]]},D={"the-chariot":{en:"The Chariot traditionally concerns determination and directed will. The two contrasting sphinxes are resting here, which gives the image a moment before movement. It invites you to ask what needs to come into alignment before you set out.","zh-CN":"战车的传统牌义与决心和有方向的意志有关。这幅画里，一深一浅的斯芬克斯伏在车前，画面停在出发前的一刻。你可以想想，有哪些力量需要先朝同一个方向用力。"},"the-sun":{en:"The Sun is traditionally associated with openness, vitality and joy. Here, the red banner billows over a rider and a white horse, with sunflowers looking out from behind the wall. The scene gives joy a physical gesture and invites you to notice where you can express it.","zh-CN":"太阳的传统牌义与开放、活力和喜悦有关。画里，红旗在白马和骑手上方扬起，向日葵从墙后探出。喜悦在这里有了具体的姿态，也邀请你留意自己在哪里可以表达它。"}};e.s(["U",0,function(e,t){return"zh-CN"===t?e.nameZh:e.name},"N",0,function(e,t,a){if("minor"===e.arcana)return"en"===t?e:e.zh;let{symbols:n,...o}=H[e.id],i="en"===t?e:{...o,symbolism:n.map(([e,t])=>({element:e,description:t}))};return"van-gogh"!==a?i:{...i,symbolism:$[e.id].map(([e,a,n,o])=>"en"===t?{element:e,description:n}:{element:a,description:o}),traditionalInterpretation:D[e.id]?.[t]??i.traditionalInterpretation}},"E",0,function(e,a,n){let o=q.Z[n];return"pentacles"===e&&(0,t.b)(a)?o.coins:"wands"===e&&(0,t.b)(a)?o.batons:"majorArcana"===e&&"sola-busca"===a?o.trumps:o[e]},"B",0,function(e,t){let a=+("zh-CN"===t);return{uprightMeaning:e.observation[a],reflectionPrompts:[e.prompt[a]],symbolism:void 0,traditionalInterpretation:void 0}}],50463)}]);